INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`,`chat_type`,`sound_id`,`language_id`,`emote_id1`,`emote_id2`,`emote_id3`,`emote_delay1`,`emote_delay2`,`emote_delay3`) VALUES
(17907,NULL,'Unicorns are noble creatures.  Make sure to always treat yours well; there are fewer things more dangerous than an angry unicorn.',0,0,0,0,0,0,0,0,0),
(18925,NULL,'You\'ll be purchasing no mount here until you\'ve proven your worth and dedication to our people.$b\nDo not return until you are considered exalted among the high elves. Away with you!',0,0,0,274,25,0,1,2,0),
(30001,'You know.. Nothing... I was more powerful then all of you.',NULL,0,0,0,0,0,0,0,0,0),
(30002,'We embrace the darkness now... Come and be lettin\' me show you its power!',NULL,0,0,0,0,0,0,0,0,0),
(30003,'Hahahaha! I be the Hazzuri Champion, what you be mon?!',NULL,0,0,0,0,0,0,0,0,0),
(30004,'I rule over Zul\'Hazu... You shall never kill me...',NULL,0,0,0,0,0,0,0,0,0),
