(52061,'The Scourge will not prevail!',NULL,0,0,0,0,0,0,0,0,0),
(52062,'Please, don\'t speak to me again. I\'m inconsolable.',NULL,0,0,0,0,0,0,0,0,0),
(52063,'He was a man of guts and guile no doubt… Not a day goes by in which I don’t think of his valorous deeds.',NULL,0,0,0,0,0,0,0,0,0),
(52066,'(Sniff, sniff) You smell that? Don\'t you just LOVE the smell of grease?',NULL,0,0,0,0,0,0,0,0,0),
(52067,'Hic! Hic!',NULL,0,0,0,0,0,0,0,0,0),
(52068,'Oh, I wandered off again. I\'m sorry.',NULL,0,0,0,0,0,0,0,0,0),
(52069,'Stormy seas out there. The sea spirits must be restless....hic!',NULL,0,0,0,0,0,0,0,0,0),
(52070,'Oh aye! I’ll take an ale if you’re buyin! Hah! ...Hic!',NULL,0,0,0,0,0,0,0,0,0),
(52071,'Hook me up!',NULL,0,0,0,0,0,0,0,0,0),
(52072,'Would you look at the tail on her! Ya know in my prime they used to call me Brick Willy because of my-- Well I won\'t go into the details but you get the idea. Bottoms up!',NULL,0,0,0,0,0,0,0,0,0),
(52073,'Yes, $c?',NULL,0,0,0,0,0,0,0,0,0),
(52074,'Yeah, okay, boss. No problem.',NULL,0,0,0,0,0,0,0,0,0),
(52075,'Oh to be young again. For me there were wars to fight, women to marry... never had the chance to be young.',NULL,0,0,0,0,0,0,0,0,0),
(52076,'Good luck on your journey, kind stranger!',NULL,0,0,0,0,0,0,0,0,0),
(52077,'What do you want?',NULL,0,0,0,0,0,0,0,0,0),
(52078,'Start doing something before I replace that target dummy with you and begin a warm up session of my own!',NULL,0,0,0,0,0,0,0,0,0),
(52079,'Oh, what a beautiful flower over there...',NULL,0,0,0,0,0,0,0,0,0),
(52080,'I love pie.',NULL,0,0,0,0,0,0,0,0,0),
(52081,'Aye?',NULL,0,0,0,0,0,0,0,0,0),
(52082,'Your mind is unfocused. Are you hiding something from me?',NULL,0,0,0,0,0,0,0,0,0),
(52083,'I\'ll get the last laugh... they\'ll see! Oh, hi $c, I didn\'t see you there.',NULL,0,0,0,0,0,0,0,0,0),
(52084,'Hiccup!',NULL,0,0,0,0,0,0,0,0,0),
(52085,'Dang! Fish aren\'t biting here either. I am gonna go back to my ol\' fishin\' hole!',NULL,0,0,0,0,0,0,0,0,0),
(52086,'Did you see? That last firework almost caught that dwarf\'s shirt on fire! Hah!',NULL,0,0,0,0,0,0,0,0,0),
(52087,'Show strength to your enemy, and we will prevail!',NULL,0,0,0,0,0,0,0,0,0),
(52090,'Wha\'sh your name?',NULL,0,0,0,0,0,0,0,0,0),
(52091,'Please, go on.',NULL,0,0,0,0,0,0,0,0,0),
(52092,'Hail traveler. If you want the latest news, head over to Vigil\'s Tavern. That\'s where most of us go to trade stories and gossip.',NULL,0,0,0,0,0,0,0,0,0),
(52095,'Gods, this is country. I have half a mind to leave them all behind and keep going. What do you say, just you and me on the Kingsroad, swords at our sides, couple of tavern wenches to warm our beds tonight?',NULL,0,0,0,0,0,0,0,0,0),
(52096,'A friend once told me something that gave me great comfort. He said \'Life is only worth a damn because it\'s short! It\'s designed to be consumed, used, spent, lived, felt. We\'re supposed to fill it with every mistake and miracle we can manage. And then we\'re supposed to let go.\'',NULL,0,0,0,0,0,0,0,0,0),
(52097,'What happened to our pigs?',NULL,0,0,0,0,0,0,0,0,0),
(52100,'Remember this laddie, pressure can either burst pipes or make diamonds.',NULL,0,0,0,0,0,0,0,0,0),
(52101,'I\'d talk to you if you smelled better. Cologne would be nice.',NULL,0,0,0,0,0,0,0,0,0),
(52102,'You lost?',NULL,0,0,0,0,0,0,0,0,0),
(52103,'Do fish ever get thirsty?',NULL,0,0,0,0,0,0,0,0,0),
(52104,'I just know my true love is out there somewhere! Medicine, law, business, engineering, these are noble pursuits, and necessary to sustain life... But poetry, beauty, romance, love, these are what we stay alive for.',NULL,0,0,0,0,0,0,0,0,0),
(52105,'You are an inspiration to us all.',NULL,0,0,0,0,0,0,0,0,0),
(52106,'Watch it, buddy!',NULL,0,0,0,0,0,0,0,0,0),
(52107,'Uh oh...',NULL,0,0,0,0,0,0,0,0,0),
(52108,'Unlike most ogres, I do know what an outhouse is for - giving you a swirlie. Now beat it.',NULL,0,0,0,0,0,0,0,0,0);
INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`,`chat_type`,`sound_id`,`language_id`,`emote_id1`,`emote_id2`,`emote_id3`,`emote_delay1`,`emote_delay2`,`emote_delay3`) VALUES
(52109,'Pleasure to meet you $n. Comin from the harbor? Next time you\'re there, give Sida my best, would ya?',NULL,0,0,0,0,0,0,0,0,0),
(52111,'*Gwenna gives you a sly wink.*',NULL,0,0,0,0,0,0,0,0,0),
(52112,'A pleasure, $n. What can I do for you?',NULL,0,0,0,0,0,0,0,0,0),
(52114,'Been a tough day? A nice ale should loosen those worries right up.',NULL,0,0,0,0,0,0,0,0,0),
(52115,'I\'ll tell you a secret. Something they don\'t teach you in your temple. The Gods envy us. They envy us because we\'re mortal, because any moment might be our last. Everything is more beautiful because we\'re doomed. You will never be lovelier than you are now. We will never be here again.',NULL,0,0,0,0,0,0,0,0,0),
(52116,'Kiss me.',NULL,0,0,0,0,0,0,0,0,0),
(52117,'Yea?',NULL,0,0,0,0,0,0,0,0,0),
(52119,'What do you want?',NULL,0,0,0,0,0,0,0,0,0),
(52125,'Greta the tittle tattle prattled on about the little metal bottle. She spat a bit of spittle on the moth that bit the cattle in a bitter battle.',NULL,0,0,0,0,0,0,0,0,0),
(52128,'How are you doing?',NULL,0,0,0,0,0,0,0,0,0),
(60010,'Welcome to the home of the Warsong Outriders.\n\nYou must be weary, honouring the Horde and our war efforts is thirsty work.\n\nStay a while and rest your bones.',NULL,0,0,0,0,0,0,0,0,0),
(60011,'It is not your words that give you weight, Your actions give you weight my friend.',NULL,0,0,0,0,0,0,0,0,0),
(60012,'To be stationed here? No greater honour.',NULL,0,0,0,0,0,0,0,0,0),
(60014,'This be our plot of land, it\'s not much, but we call it home and home is where the heart is.',NULL,0,0,0,0,0,0,0,0,0),
(60016,'Welcome, weary traveler!\n\nWhat will be your guilty pleasure this time? Drinking? Gossiping? Adventuring?\n\nWhats wrong?\n\nI\'m a mage and I serve drinks! Don\'t tell anyone, but it\'s the easiest way to make money that I\'ve ever heard of.',NULL,0,0,0,0,0,0,0,0,0),
(60301,'I am not fond of having to turn down a good chunk of our autonomy, no. But as I said, my people\'s future comes first. Besides. The goddess of our ancestors has guided the Kaldorei well. Who am I to doubt their goddess? I\'ve seen her power first hand, and so have you. Whether she is the right thing for my people is another question. One only the future will answer.',NULL,0,0,0,0,0,0,0,0,0),
(60312,'The Kaldorei have arrived and have started preparations. Why not go and check up on their progress? They have setup in the Golden Dawn Institute. It is the floating building where our teleport to Stormwind resides. Once you are done return here.',NULL,0,0,0,0,0,0,0,0,0),
(60313,'Hello again friend, I have heard of all the good you\'ve done for our cause. I take it you\'re here as Lady Windrunner\'s emissary for the summit?',NULL,0,0,0,0,0,0,0,0,0),
(60316,'Grrrr... Called Snarles Shadowpaw. Work is good if you need killing. Murky Waters take contract to do work others donӴ like doing. You want to have something kill you come to right place. Ask with bag of gold...','Grrrr... Called Snarles Shadowpaw. Work is good if you need killing. Murky Waters take contract to do work others donӴ like doing. You want to have something kill you come to right place. Ask with bag of gold...',0,0,0,0,0,0,0,0,0),
(60350,'You will die before the might of Gilneas.',NULL,0,0,0,0,0,0,0,0,0),
(60351,'You won\'t leave here alive, outsider!',NULL,0,0,0,0,0,0,0,0,0),
(60352,'I fight for my king, you fight for your life!',NULL,0,0,0,0,0,0,0,0,0),
(60353,'My sword is stained with the blood of my enemies, and yours will soon join them.',NULL,0,0,0,0,0,0,0,0,0),
(60354,'You and the other rebels will be hunted like the cattle you are.',NULL,0,0,0,0,0,0,0,0,0),
(60355,'You will find no mercy here, just the wrath of Greymane.',NULL,0,0,0,0,0,0,0,0,0),
(60356,'For the Crown!',NULL,0,0,0,0,0,0,0,0,0),
(60357,'In the name of Genn Greymane!',NULL,0,0,0,0,0,0,0,0,0),
(60358,'In the name of the Light!',NULL,0,0,0,0,0,0,0,0,0),
(60359,'Justice shall be served.',NULL,0,0,0,0,0,0,0,0,0),
(60360,'Back to the shadows!',NULL,0,0,0,0,0,0,0,0,0),
(60446,'A great power lurks, and I seek to combat it. Those who wronged me shall pay the ultimate price, and I will make sure they suffer. You are going to be the one who helps me, and perhaps I shall reward you for your efforts.\n\nWell, make yourself at home, there is much to do and much to discuss.',NULL,0,0,0,0,0,0,0,0,0),
(60447,'You\'re going to scare off all the fish!',NULL,0,0,0,0,0,0,0,0,0),
(60448,'You wouldn\'t happen to have a few coin on you, huh? I need it for the next time we stop somewhere.',NULL,0,0,0,0,0,0,0,0,0),
(60449,'I will never care of your rank, I respect strength above else. Prove yourself to be worthy of my axe and I will die for you. Do not mistake these words for mutiny, I will respect your orders and will not question them.',NULL,0,0,0,0,0,0,0,0,0),
(60450,'Hey there friend, Gary is the name! If you\'re looking to spend your coin then heres the place, you could potentially even triple your money through me if you got luck on your side! So, what say you swashbuckler, got the heart for it?',NULL,0,0,0,0,0,0,0,0,0),
(60452,'Welcome aboard, we Bloodsail treat eachother well at the least, if you remain loyal.',NULL,0,0,0,0,0,0,0,0,0),
(60454,'Just because I\'m old don\'t think I\'m weak, ye understand young one? Ye let yer guard down for but a moment and Old-Tide Sam will pull you under.',NULL,0,0,0,0,0,0,0,0,0),
(60455,'No better place to rest up then on the ship! The rocking of the waves is almost gentle don\'t you agree?',NULL,0,0,0,0,0,0,0,0,0),
(60459,'Ey mon, you be looking like you could use a few trinkets, let Vil\'do tell you what you be needing.',NULL,0,0,0,0,0,0,0,0,0),
(60460,'Looking for the good stuff huh? You\'ll find it no where else.',NULL,0,0,0,0,0,0,0,0,0),
(60465,'What brings a young $r all the way up here? I can only assume you seek my counsel.',NULL,0,0,0,0,0,0,0,0,0),
(60470,'Who are you?! Begone, this is my home, you do not belong here!',NULL,0,0,0,0,0,0,0,0,0),
(60471,'The forests beauty is unmatched, the winds flowing through the trees, the moonlight dotting the landscape. Yet, beneath it all, there is a darkness that lurks, hidden beneath the veil of it all. This place used to be so full of life and harmony, but now there is more predators then we can count, and our allies in the forest have turned to nothing more then roaming thugs.\n\nYou can sense it, can\'t you, as if you could wake from the dream at any moment.',NULL,0,0,0,0,0,0,0,0,0),
(60472,'Ashenvale is growing more and more dangerous by the day.',NULL,0,0,0,0,0,0,0,0,0),
(60473,'','We must remain ever vigilant of not only dangers from abroad, but from within. Teldrassil has seen an increase in domestic disturbances of late, demanding more of my forces be sent out on patrol and investigations opened all across the forest.',0,0,0,0,0,0,0,0,0),
(60474,'Welcome to Darnassus, crown jewel of Teldrassil.$B$BThis city serves as the heart and soul of the Kaldorei, and for good reason. Its grace and beauty mirrors that of our culture, our legacy.',NULL,0,0,0,0,0,0,0,0,0),
(60476,'What you doing all the way out here $R?',NULL,0,0,0,0,0,0,0,0,0),
(60477,'Be comfy, the fire pits here are warm, and you be warm too!',NULL,0,0,0,0,0,0,0,0,0),
(60478,'We Maul\'ogg have been here for long time, and we gonna stay here for long time! Just cause others think they can push us around doesn\'t mean anything! With Lord Cruk\'Zogg we can do anything that we want on the island.\n\nWe\'re stronger then all of them, and we\'re gonna be pushing them around soon!',NULL,0,0,0,0,0,0,0,0,0),
(60479,'Hey there, I\'m Wincing Willy Pal! Heard good things about you, the only reason we\'re talking right now. My job is to oversee supplies coming from the great seas and keep them here until we can allocate them elsewhere.',NULL,0,0,0,0,0,0,0,0,0),
(60480,'You look familiar, you one of the new crew members?',NULL,0,0,0,0,0,0,0,0,0),
(60481,'Another Bloodsail huh? Not often someone wanders around out here and just shows up, what you looking to help?',NULL,0,0,0,0,0,0,0,0,0),
(60483,'The path ahead will be different for you, you no longer adapt to nature, nature adapts to you.',NULL,0,0,0,0,0,0,0,0,0),
(60484,'The path of a Forsaken hunter differs from that of others. We do not adapt to nature, but bend nature to adapt to us.',NULL,0,0,0,0,0,0,0,0,0),
(60485,'The path ahead will be different for you, you no longer adapt to nature, nature adapts to you.',NULL,0,0,0,0,0,0,0,0,0),
(60486,'The path ahead will be different for you, you no longer adapt to nature, nature adapts to you.',NULL,0,0,0,0,0,0,0,0,0),
(60487,'The path ahead will be different for you, you no longer adapt to nature, nature adapts to you.',NULL,0,0,0,0,0,0,0,0,0),
(60488,'The beasts of this world do not trust the undead. The Cult of Forgotten Shadow possesses a solution for this, however.',NULL,0,0,0,0,0,0,0,0,0),
(60496,'Ahoy matey, I am very curious to see what new chapter for the Bloodsail Buccaneers you will be painting. I will be watching the Cap\'n\'s lodge for a while but when ye come here to rest or spend some alone time I will be gone.',NULL,0,0,0,0,0,0,0,0,0),
(60500,'So much to do in such a short amount of time, not to mention all the competition, and those blasted Venture Co. lurking about.',NULL,0,0,0,0,0,0,0,0,0),
(60502,'Not many people come back here. You useful? Think you could do some handy work for me?',NULL,0,0,0,0,0,0,0,0,0),
(60503,'I sense something about you, something.. Different. Perhaps we will meet again, until then, leave me be, I have much work to do, and I do not desire to be interfered.\n\nUnless you\'re looking for a fight mortal, if so, it can be arranged.',NULL,0,0,0,0,0,0,0,0,0),
(60504,'You heard word from Booty Bay? I\'m expecting a shipment.',NULL,0,0,0,0,0,0,0,0,0),
(60507,'Stonetalon Peak may be a place of harmony, but we must be vigilant to keep it this way.',NULL,0,0,0,0,0,0,0,0,0),
(60510,'Nothing is greater than fishing!',NULL,0,0,0,0,0,0,0,0,0),
(60511,'Ey mon, you looking to learn to work with nature?',NULL,0,0,0,0,0,0,0,0,0),
(60512,'Well, this is new, I don\'t often get visitors.',NULL,0,0,0,0,0,0,0,0,0),
(60526,'It is in the fringes of the world that hope shines the brightest, never forget that even a dim torch is still burning.',NULL,0,0,0,0,0,0,0,0,0),
(60527,'I am in my homeland, defending what is important to me, be it from those crazed zealots, or from the undead themselves, Light\'s Point will establish what once was.',NULL,0,0,0,0,0,0,0,0,0),
(60528,'My family called Lordaeron home once, heh, believe it or not. Valuable money was to be made from ore and jewelcrafting that we Stonefury were once known for many years ago! Now all that\'s left of my family\'s legacy is smouldering ruins, piles of stone, and burnt wood. Not to mention the corpses!$B$BIf I\'m going to fight for anything, it may as well be here.',NULL,0,0,0,0,0,0,0,0,0),
(60529,'Welcome to Light\'s Point, make yourself at home, should you not be tainted by either the plague of undeath, or the plague of zealotry.\n\nThe Scarlet Crusade that occupy the region are fervored in a bloodlust against all things, both living and dead. They view the world around them as hostile, and will need to be put down should the true light of what once was to shine through.',NULL,0,0,0,0,0,0,0,0,0),
(60531,'Well, you\'ve been a much more friendly face to us, not even our own comrades in arms were willing to simply come up and talk.\n\nI thought we would be lauded as heroes, or at the least returned to with open arms, and here we are, treated as villains after surviving the expedition to the north on behalf of the crusade. It sickens me to know how many died to bring the fight to the undead just for things to have fallen apart as they have here.\n\nEither way, apologies for my rudeness, I am Captain Haroldson, of the Embertide in the Scarlet Fleet, or at the least, what is left of it, anyway, after everything that happened with that doomed expedition.',NULL,0,0,0,0,0,0,0,0,0),
(60532,'Out of all the ships to make it back we were the only one, you believe that luck?... Hic!\n\nThere were much better men then me, and honestly, I don\'t even want to be here after everything that happened up north. Just, toss me in the water already.',NULL,0,0,0,0,0,0,0,0,0),
(60538,'I am a seasoned wyvern trainer, $c. It feels like just yesterday when the tauren and orcs liberated them from the harpies of Stonetalon. They have been loyal friends to the Horde ever since.',NULL,0,0,0,0,0,0,0,0,0),
(60540,'Well, not often we see outsiders! Come, shelter yourself, the winter can surely get harsh!',NULL,0,0,0,0,0,0,0,0,0),
(60541,'Wow, what are you? Are you one of the people that Inunquaq was going to see in the southlands?!\n\nYou\'re lucky to come here, many travel to Kaneq\'nuun to see the great shiny spirit that flys through the sky, maybe you\'ll see it too!',NULL,0,0,0,0,0,0,0,0,0),
(60542,'Welcome to Kaneq\'nuun, you certainly look much different than anything I\'ve seen, but as long as you\'re friendly, you are welcome. I am Panukuki, the elder here, if you have any questions, feel free to bring them to me.',NULL,0,0,0,0,0,0,0,0,0),
(60543,'The fish are always biting out here',NULL,0,0,0,0,0,0,0,0,0),
(60549,'Greetings traveler. If you are looking to reach our ancient homeland of Kalimdor to the west, you will need passage by boat. One of our ships from Auberdine makes regular stops here in Stormwind.$B$BDo not fret if the boat is not here; it will arrive in due time.',NULL,0,0,0,0,0,0,0,0,0),
(60606,'The growing magical energies surrounding Karazhan have been a great cause for concern within the Kirin Tor. I have ventured here of my own will to study the mysteries that seem to be growing more bold with the passing of time. Perhaps you are willing to assist the Kirin Tor in uncovering the unknown for the greater good?',NULL,0,0,0,0,0,0,0,0,0),
(60607,'Oh, been loyal to ol\' Orvak me whole life, they tossed me out with the others, and we\'re all that remain.',NULL,0,0,0,0,0,0,0,0,0),
(60611,'Well, it sure is a nice place, isn\'t it?',NULL,0,0,0,0,0,0,0,0,0),
(60621,'We have many allies across the Great Sea, located far to the east within the Eastern Kingdoms. The boat that arrives at this dock leads to the harbor of the human city of Stormwind, the heart of the Alliance.$B$BIf the boat is not here, have patience. It shall arrive shortly.',NULL,0,0,0,0,0,0,0,0,0),
(60622,'It has been a long time since a mortal has walked these halls. As much as I have my distaste for you all, I understand that we require your aid.',NULL,0,0,0,0,0,0,0,0,0),
(60623,'This here boat will lead ye all the way to Sparkwater Port in Durotar, the goblins be needin\' all sorts a things from us, and we\'re more then happy to supply them for weapons.',NULL,0,0,0,0,0,0,0,0,0),
(60624,'Me and my brother Tizak run this zeppelin route! We could certainly use some new parts to repair the thing soon, but making the trip through the Badlands has been stressful! This zeppelin here leads all the way to Orgrimmar, back to the heartland of the Horde.\n\nCareful when the zeppelin is coming in, it can be a close call!',NULL,0,0,0,0,0,0,0,0,0),
(60625,'Heh, this old rustbucket doesn\'t steer the greatest. Damn is it hard getting it through the rough jagged landscape of the Badlands, but it\'s managed well enough thus far! If you\'re looking for an express ticket to Kargath, then there is no better route then on this old girl, the zeppelin is certainly a faithful one!\n\nOh, and don\'t mind the bumpy ride, it needs some new parts, and doesn\'t really stop right.',NULL,0,0,0,0,0,0,0,0,0),
(60626,'Hey there, you looking to head to the great plains of Mulgore? Well, then you\'re in luck, we set up a new route from Orgrimmar to Thunder Bluff, it\'s quite the scenic view, give it a go.',NULL,0,0,0,0,0,0,0,0,0),
(60628,'Why, is there anything I can help you with? Unless you are seeking knowledge of the arcane, I may not be of assistance.',NULL,0,0,0,0,0,0,0,0,0),
(60629,'We dwarven mages are that of The Azurestone Order, long ago when the very caves of Ironforge were being mined, we came across an old, and rather magically potent stone. This stone was studied by the mages of Dalaran, and has been kept within our hands since that very day.\n\nIt is with this stone that many of the first dwarven mages had gotten their footing within the realm of arcana. If you see any of our kin that are naturally gifted with magic, guide them here.',NULL,0,0,0,0,0,0,0,0,0),
(60631,'<N\'ribbi stares deep into your soul>.',NULL,0,0,0,0,0,0,0,0,0),
(60636,'Welcome to Southfury Trading Company, friend! Did ya come here for business? If you need something shipped, our first-class caravaneers got ya covered.\n\nOr are ya carryin\' a bit too much coin around and expectin\' some good-for-nothin\'s to come after ya? No problem, we got some well-trained muscle to protect your pretty bottom! Or maybe you\'re lookin\' for some exotic wares from the South Seas? If money can buy it, we will get it for ya, promised!\n\nSouthfury Trading Company - You got coin and we want it!',NULL,0,0,0,0,0,0,0,0,0),
(60640,'The Hand of Wrath is a military unit led by Executor Rotheart. It is the iron hand of the Horde, crushing its enemies. The Hand serves the Warchief and the leaders of the races of the Horde.\n\nFounded out of the Forsaken Vanguard by the order of the Dark Lady as a way to forge brotherhood between all races of the Horde in the fires of war. Officers are straight down the tunnel if you\'re looking to join or have some business with us. If not then stop wasting my time.',NULL,0,0,0,0,0,0,0,0,0),
(60643,'Hands off my haul bub!',NULL,0,0,0,0,0,0,0,0,0),
(60644,'I bear the knowledge of the Shen\'dralar, I am a Highborne of Eldre\'thalas and I know a great deal about our world. Since you can aid me to gain even more knowledge I am at your service, Captain.',NULL,0,0,0,0,0,0,0,0,0),
(60645,'Welcome to the Golden Moon Circus, the home of the Golden Moon Traveling Troupe.\n\nEnjoy yourselves as we entertain you through our magical acts and trickery - but be wary that we are not responsible for any burning, choking, drowning, money loss, body loss or loss of mind that might or might not happen to you.\n\nThank you for your understanding and have a pleasant day.',NULL,0,0,0,0,0,0,0,0,0),
(60648,'Greetings.\n\nOn this plane I am known as Olom, a fisher between the realms. You are a new face... I think?\n\nAs a younger orc I broke free from my demonic master, so I was overjoyed to finally discover there were others out there after so many years who have sided against the Legion. It gladdens my heart to know that a new age and style of warlock is growing.\n\nPipnam here reports many evils brewing. So we need to be ready for the worst, as our name suggests.\n\nWe are the Ered Ruin. The Doom Guard.\n\nWelcome.',NULL,0,0,0,0,0,0,0,0,0),
(60656,'All that I am: anger, cruelty, vengeance, death and decay - I bestow upon those who welcome the cold embrace of undeath.\n\nGaze now upon the lands before us.\n\nThe Scarlet Crusade scurries to undo my work, while Light\'s Hope stands defiantly against us - for they are but a blemish upon the Plaguelands.\n\nThey must all be shown the price of their defiance.\n\nWhere you tread, blight will follow.\n\nGo now and claim these lands in the name of Ner\'zhul and The Lich King. ALL. MUST. DIE!',NULL,0,0,0,0,0,0,0,0,0),
(60660,'The School was not always quel’dorei you know, its origins are far more ancient than even Ranger-Lord Dragonstrider knew of. After the War of the Ancients, many worgen still roamed the forests of Kalimdor after their unfortunate release from the Scythe of Elune. Demons and satyrs also ran rampant as well, innocents slain constantly. Brave sentinels and highborne sorcerers alike put aside their differences and created a new order of warriors to wipe out the vicious monsters that stalked the night. The “Thero’anir” or “Dragonhawks” in your tongue were infused with draconic blood to match the ferocity of their foes.\n\nSadly, only Cydas and I are all that remain of the original Thero’anir. Perhaps with Ranger-Lord Bladesong’s resurgence of the order, the School will reach its zenith again.',NULL,0,0,0,0,0,0,0,0,0),
(60661,'Welcome Friend!\n\nThis sacred place is home to the Macrochelys of Azeroth, defenders of horde and alliance, elemental executioners, dragon hunters, and god slayers.\n\nThis is our home and home is where the heart is.',NULL,0,0,0,0,0,0,0,0,0),
(60668,'Lok\'tar ogar!\n\nIn this camp we do not draw blood from each other, no matter what clan you come from. Here we heal our wounds and rest.\n\nTo prepare for the next battle ahead, against the pinkskins.\n\nThru blood, fire and death!',NULL,0,0,0,0,0,0,0,0,0),
(60670,'Glad you are with us! There is no telling what awaits us on Shalandis, but we cannot let our new allies down.',NULL,0,0,0,0,0,0,0,0,0),
(60700,'I\'ve found my calling after the injuries of the last war in preparing the finest meals I can provide. \n\nCome and have your fill before heading back to work!',NULL,0,0,0,0,0,0,0,0,0),
(60702,'Everyone wants to know the secret to my brew, but it’s something I can\'t teach.\n\nI learned from an eccentric man riding a turtle a few years back.',NULL,0,0,0,0,0,0,0,0,0),
(60703,'It\'s really inconvenient to come here to eat every day, but I just can\'t get enough of Sarn\'s brew.\n\nHave you seen Nantai work? I could watch that all day.',NULL,0,0,0,0,0,0,0,0,0),
(60704,'<She claps excitedly in your face before giggling wildly.>\n\nStep carefully around this estate! Lots of questionable types around, even the flowers are scared!\n\nCan you hear them?!',NULL,0,0,0,0,0,0,0,0,0),
(60710,'A foul darkness encroaches in these lands, growing ever more potent. It is up to us to stop the demonic taint.\n\nDo you have what it takes to stalk demons, and rid them from the world?',NULL,0,0,0,0,0,0,0,0,0),
(60727,'Welcome to Theramore, make yourself at ease. I am Colonel Breen, commander of the defense of Theramore.\n\nWe are always looking for a pair of brave hands. If you\'re looking for work, perhaps you could be of assistance to the Theramore Guard.',NULL,0,0,0,0,0,0,0,0,0),
(60728,'Someones gotta keep this lighthouse running, and I suppose that someone is me.\n\nI got a lot of work to do, you need anything?',NULL,0,0,0,0,0,0,0,0,0),
(60729,'It\'s dangerous out here, no doubt about that! Especially with all of the wildlife lurking around.',NULL,0,0,0,0,0,0,0,0,0),
(60730,'We have a lot of work to do here on the frontier, so unless you\'re here to help, please do let me work.',NULL,0,0,0,0,0,0,0,0,0),
(60731,'We have all sorts of books stored, chaptering much of the things we have come across within Kalimdor. If you\'re seeking some rare knowledge, you\'ve certainly come to the right place.',NULL,0,0,0,0,0,0,0,0,0),
(60732,'The shores have been growing more concerning as of late, let us pray that things will not escalate further.',NULL,0,0,0,0,0,0,0,0,0),
(60733,'The docks are my domain, if you have anything that needs to be sent, or delivered, let me know.',NULL,0,0,0,0,0,0,0,0,0),
(60748,'Do you know where you are walking mortal? This place has been here long before your races existence. The Emerald Sanctum is a hallowed ground. Your mere steps upon the verdant grass tarnishes the beauty of this place. Your vile smell lingers upon the air.$B$BYou must leave, it will not be long until the rest of the Green Dragonflight is awoken.$B$BOur eternal duty has arrived, and as The Awakener, I have put out the call to stir those lost in slumber. They will arrive, it is only a matter of time now, and you will not get in the way, $r.$B$BDarkness swirls, festering upon the sleepless realm, I will put an end to it.',NULL,0,0,0,0,0,0,0,0,0),
(60749,'So, you be from the Horde, yes?\n\nMy name be Taza\'go, I once fought beneath Ukorz Sandscalp as his champion, but those times be long passed mon.\n\nThe Sandfury be scattered, and disillusioned. Others left before, and after we did, it not be long until Zul\'Farrak is left an abandoned ruin for everything evil, and cursed that took place in that city.\n\nPerhaps you can help us, for we need it.',NULL,0,0,0,0,0,0,0,0,0),
(60750,'Don\'t be scared, Viceclaw don\'t be pinchin\' nobody I don\'t tell em too!',NULL,0,0,0,0,0,0,0,0,0),
(60751,'Hey mon, we don\'t get many visitors in this village. I work on the leather here, you looking for anything specific?',NULL,0,0,0,0,0,0,0,0,0),
(60752,'The ancestors be upset with our actions in the old city. I seek guidance for how to gain redemption, and to lead us to a new destiny, away from the taint of Sandfury evil.',NULL,0,0,0,0,0,0,0,0,0),
(60753,'Welcome to Sandmoon Village, this place is lead by Taza\'go, he is leader here, one I would trust to follow to the ends of this earth mon.\n\nIf anyone can restore our lost honor, it be him.',NULL,0,0,0,0,0,0,0,0,0),
(60754,'Be careful in Tanaris, it is a harsh place for outsiders, void of water.\n\nThe sun itself has withered away the strongest of our kind, don\'t think yourself immortal to the heat.',NULL,0,0,0,0,0,0,0,0,0),
(60759,'Our mission here is of an utmost importance. The Dark Portal radiates with fel energy, who knows if it is even still active.',NULL,0,0,0,0,0,0,0,0,0),
(60760,'I hate ogres.',NULL,0,0,0,0,0,0,0,0,0),
(60761,'I am Jaiymu, son of Taiymu. What do you need friend?',NULL,0,0,0,0,0,0,0,0,0),
(60762,'I am well versed crafting in the old methods, perhaps you could use a repair to let me refine my skills.',NULL,0,0,0,0,0,0,0,0,0),
(60763,'Dark magic aids us in battle, and empowers our spirits. The Blood Fury that flows through our veins is a resource that can be tapped, and aided by the powers I can conjure.',NULL,0,0,0,0,0,0,0,0,0),
(60764,'There are darker powers at play, always, do not think yourself as smart enough to avoid their tricks, be wary, for you never know who, or what might be watching.',NULL,0,0,0,0,0,0,0,0,0),
(60765,'I have ridden across many battle fields, and slain many foes, but it is only now that I feel caution for what lies ahead. I trust Karfang with every ounce of my blood, but I do not know if we share the same values with this \'New Horde\' across the world.\n\nPerhaps it is truly for the best, and perhaps it may be our downfall, we shall see in time.',NULL,0,0,0,0,0,0,0,0,0),
(60766,'What are you looking for outsider?',NULL,0,0,0,0,0,0,0,0,0),
(60769,'What is it that you want, can you not see that I am busy whelpling?',NULL,0,0,0,0,0,0,0,0,0),
(60770,'My name is Karfang, I am leader here.\n\nMy people should cause you no harm, lest you insult, or bother them too much. There are many things to discuss, and many things to do for us to secure our place in this world.\n\nThe Blackrock Clan find themselves manipulated by greater forces. The Old Horde is a shell of what it once was, and I will not allow my people to follow them into madness.',NULL,0,0,0,0,0,0,0,0,0),
(60772,'I am Councillor to Karfang, I advise him on all matters. Both internal and foreign.\n\nPerhaps you bring news from beyond this charred valley?',NULL,0,0,0,0,0,0,0,0,0),
(60773,'We have ale if you need it, or food if you need that, what will it be?',NULL,0,0,0,0,0,0,0,0,0),
(60774,'You are lucky we are on good terms outsider, hold your tongue and your ill words, I am used to killing those outside of the clan.',NULL,0,0,0,0,0,0,0,0,0),
(60775,'I am the one that trains the worgs for hunting, killing, and roaming.\n\nI am responsible for our best specimens, and our most useful allies. Now, what is it you want outsider?',NULL,0,0,0,0,0,0,0,0,0),
(60778,'A clenched fist speaks louder than a hundred words.',NULL,0,0,0,0,0,0,0,0,0),
(60780,'Why hello there, and welcome to Livingstone Croft, make yourself at home, the only thing I ask is that you wipe your feet off outside before you come in!',NULL,0,0,0,0,0,0,0,0,0),
(60781,'So many damned critters around here, keep disturbing the crops and making our lives even more difficult then it needs to be...\n\nAhh, sorry about that, what can I do for you?',NULL,0,0,0,0,0,0,0,0,0),
(60782,'All of this work being done, its exciting, I can\'t wait to see the whole city finished!',NULL,0,0,0,0,0,0,0,0,0),
(60784,'Azeroth sure is a mystical place, the more you read the more you can find out.',NULL,0,0,0,0,0,0,0,0,0),
(60786,'I look after a lot of the horses for the Stromgarde Cavalrymen, no doubt you\'ve seen them around, they often keep the main road between here and Refuge Pointe secured, as much as they can, anyway.',NULL,0,0,0,0,0,0,0,0,0),
(60787,'It is only a matter of time until things get much better.',NULL,0,0,0,0,0,0,0,0,0),
(60788,'Welcome to Gallant Square, our section of the city. Don\'t let your guard down, for as much progress as we are making it can all be destroyed within a matter of minutes.\n\nThe Ogres and Syndicate still lurk within other parts of the city, and cause us much nuisance, so keep your wits about you on the way in and out.\n\nSo, what can I do for you?',NULL,0,0,0,0,0,0,0,0,0),
(60789,'Don\'t be scared, come come! I sell all sorts of magical supplies and stuff, perhaps you\'re looking for what I\'m selling!',NULL,0,0,0,0,0,0,0,0,0),
(60790,'No need to be shy, look around, and buy what you need.',NULL,0,0,0,0,0,0,0,0,0),
(60791,'Welcome, I hope you can find some rest within this hellish place.\n\nThis is Nethergarde Keep, established once the Dark Portal opened and the First War had begun years ago. We have been assigned to watch over it, and report magical irregularities should they arise.\n\nIf you see anything unusual, let us know.',NULL,0,0,0,0,0,0,0,0,0),
(60792,'We\'ve seen all manner of foe out there, from ogre, to orc, to demon. It is only a matter of time before they grow bold enough to strike at us.\n\nWe will be more then prepared for when they make such an action.',NULL,0,0,0,0,0,0,0,0,0),
(60793,'Make sure you don\'t cause any trouble here, we have more then enough problems with all of the fel-warped beasts lurking in the wasteland.\n\nOr maybe you\'ve come to this frontier in order to offer assistance.',NULL,0,0,0,0,0,0,0,0,0),
(60794,'So many magical fluctuations, so much warping of genetics, it almost makes a gnomes head spin with the possibilities of it all!\n\nThere\'s research to be done $R, Research to be done!\n\nOh, right. I\'m Wigglestip, Lead Analyst at Nethergarde, a pleasure to make your acquaintance.',NULL,0,0,0,0,0,0,0,0,0),
(60795,'I\'m growing restless behind these blasted stone walls, I\'ve crushed too many demon skulls to be wasting away here.\n\nNames Harguf, I\'ve been here quite a long time, what can I do for you?',NULL,0,0,0,0,0,0,0,0,0),
(60799,'You are surely wondering what we are doing here.\n\nUnderstand me correctly, we do not like the war.\n\nWe do not go into battle for pride or honor. We don\'t care about the squabble between the Alliance and the Horde.\n\nEach side has its children and each child should be able to grow up happily.\n\nThe brigade wants to preserve this world and protect their children.\n\nSo, now it\'s up to you to decide. If you join us, take this butterfly. It will sit on your heart and on your tabard. Then you will begin to understand.',NULL,0,0,0,0,0,0,0,0,0),
(60802,'Greetings, soldier. Have you come to fend off the nefarious black dragonflight? There’s tension in the air... I can feel it. The closer we get to taking down the new leaders of the flight, the closer we get to feeling safe again.',NULL,0,0,0,0,0,0,0,0,0),
(60806,'Until you rid your heart of anger, your growth will remain forever stunted.',NULL,0,0,0,0,0,0,0,0,0),
(60813,'May your journies guide you to interesting places, what can I do for you?',NULL,0,0,0,0,0,0,0,0,0),
(60816,'Welcome to Red Cloud Roost, It is here we prepare many of the new and young wyvern to live as loyal companions to the Horde. If they are not trained properly they can become unruly, and savage.\n\nYou may find many untamed wyvern within Stonetalon Mountains if you desire to see just how vicious they can become.',NULL,0,0,0,0,0,0,0,0,0),
(60817,'I have been training the wyvern here for some time now, making sure that they keep their primal instincts in check.',NULL,0,0,0,0,0,0,0,0,0),
(60818,'Being new around here certainly has its ups and downs, at the least I learn from the best.',NULL,0,0,0,0,0,0,0,0,0),
(60822,'These damned Quillboar are always stronger than I anticipate, never underestimate a foe.',NULL,0,0,0,0,0,0,0,0,0),
(60823,'It is up to us to ensure that the spirits transition to the world beyond. We are to watch over them, and to keep their memories and experiences passed down from generation, to generation. In a way, we are the keepers of the past, and the present.',NULL,0,0,0,0,0,0,0,0,0),
(60824,'You can always feel the spirits no matter where you are, take comfort in knowing that your ancestors will guide the path ahead.',NULL,0,0,0,0,0,0,0,0,0),
(60825,'Too see, is to believe.',NULL,0,0,0,0,0,0,0,0,0),
(60826,'Do not fear what comes next, rejoice to share this experience with those around you.',NULL,0,0,0,0,0,0,0,0,0),
(60827,'Arathor has long been at war with the trolls, and we shall be the ones to end it.',NULL,0,0,0,0,0,0,0,0,0),
(60832,'I put in a lot of work within Shadowforge, to think it all meant nothing.',NULL,0,0,0,0,0,0,0,0,0),
(60833,'Exiled, you believe that?!\n\nI was the foreman that looked after the Shadowforge Miner\'s Union. For years I carved the tunnels of the city itself and this is the thanks I get? They said I was lucky to have survived my failures. No doubt they expected me and my group to just die off to some Blackrock scum.\n\nThey will pay for this.',NULL,0,0,0,0,0,0,0,0,0),
(60834,'Oh, been loyal to ol\' Orvak\' me whole life, they tossed me out with the others, and we\'re all that remain.',NULL,0,0,0,0,0,0,0,0,0),
(60846,'Baaaa!',NULL,0,0,0,0,0,0,0,0,0),
(60850,'There are many things to learn, and much wisdom to be passed down.\n\nWe exiles have a lot to teach the other races of this world.',NULL,0,0,0,0,0,0,0,0,0),
(60851,'Your curious face tells me you want to know who we are or what we do...\n\n<Ley-Technician Vorthal sighs exasperatedly.>\n\nWe are the Thalassian Alliance, an organization with the noble goal of helping refugees, my people, the High Elves, and of course, supporting our new Alliance allies in whatever they do.\n\nNow, if you will excuse me, I need to fix this blasted orb, so, unless you happen to be an expert in ley lines or mana currents, go entertain yourself elsewhere and stop wasting my time!',NULL,0,0,0,0,0,0,0,0,0),
(60854,'Get out of my shack.',NULL,0,0,0,0,0,0,0,0,0),
(60855,'Watch yourself, the Garrison Armory has been over run.',NULL,0,0,0,0,0,0,0,0,0),
(60856,'The howling winds of Tanaris whisper things to me, and I can not speak back... Strange it is to be lost like this.',NULL,0,0,0,0,0,0,0,0,0),
(60857,'Make yourself welcome here, there be a lot to do!',NULL,0,0,0,0,0,0,0,0,0),
(60858,'Westfall. Once, land of prosperity. Now, nothing more than a wasteland.',NULL,0,0,0,0,0,0,0,0,0),
(60859,'I\'m busy, pal.',NULL,0,0,0,0,0,0,0,0,0),
(60860,'Saludos camarada. Me alegra ver a alguien con tanta energía y ganas como tú. Alguna vez me sentí vivo, ahora no soy más que escombros y no sé cómo puedo seguir aquí. Tengo la sensación de que he reencarnado varias veces en este mundo.$B$BRecuerdos borrosos vienen a mí... ¿Un cofre? ¡Cuidado! Está lleno de trampas, ¡es un suicidio!... Me ahogo, creo que en la próxima vida aprenderé a nadar...$B$BUff, no sé qué ha sido eso pero lo recuerdo y me dan escalofríos. Mejor ten eso en cuenta.',NULL,0,0,0,0,0,0,0,0,0),
(60862,'<The body lays unmoving.>',NULL,0,0,0,0,0,0,0,0,0),
(60863,'<You can feel your ancestors gaze upon you>.',NULL,0,0,0,0,0,0,0,0,0),
(60864,'<You can feel your ancestors gaze upon you>.',NULL,0,0,0,0,0,0,0,0,0),
(60865,'<You can feel your ancestors gaze upon you>.',NULL,0,0,0,0,0,0,0,0,0),
(60869,'It\'s almost insulting being placed out here, you do one wrong thing and then you\'re sent out to the fringes to deal with problems...\n\nI guess someone has got to get their hands dirty.\n\nYou looking for work, cause we can use some help.',NULL,0,0,0,0,0,0,0,0,0),
(60870,'All sorts of stuff be goin\' on just around the ridgeline, keep your eyes peeled, and ye be seein\' Dark Irons about.\n\nI\'m here to find out what they be up to.',NULL,0,0,0,0,0,0,0,0,0),
(60872,'Ironforge is nice and all, but I kind of miss Gnomeregan, it was just, cozy, and offered all kinds of progress in many fields you know?\n\nWell, maybe not, but either way it isn\'t all bad, there are still things to figure out and mysteries to solve.',NULL,0,0,0,0,0,0,0,0,0),
(60873,'The wolf looks at you with fear in its eyes.',NULL,0,0,0,0,0,0,0,0,0),
(60874,'I hope you are well, is there anything that you require?',NULL,0,0,0,0,0,0,0,0,0),
(60875,'Two plus three times four... What do you want?',NULL,0,0,0,0,0,0,0,0,0),
(60877,'The light watches over all, do not forget that.',NULL,0,0,0,0,0,0,0,0,0),
(60879,'What is it you want? I\'m busy, so move it along.',NULL,0,0,0,0,0,0,0,0,0),
(60880,'Since the death of Grommash Hellscream, our clan have been scattered around kalimdor, from Ashenvale down to the Thousand Needles.\n\nNowadays, only the most fierceful leaders of the Warsong Outriders are listened still. But one day, sooner or later... A new Warchief will arise! We are the ones who built Orgrimmar in a few days. All the citizens witness what have done the real sons of the Horde!\n\nWe\'ll never let some filthy night elves continue their outrageous sabotage.\n\nThe War-effort has no end. As long as the eternal nomadry will run the entire Kalimdor.',NULL,0,0,0,0,0,0,0,0,0),
(60884,'Well look who stumbled on this hole in the wall! Ya found our hideaway, those who\'re lookin to get rich or die grindin. Ya got coin? We\'ll take it. Ya thirsty? Plenty o\'kegs inside.\n\nWork a bit on your skills, or just stare listlessly at a wall, we don\'t care here. Make do and lay low til they stop lookin for ya, then get back out there and find yer wealth!',NULL,0,0,0,0,0,0,0,0,0),
(60888,'Aye there! Welcome to the Talon\'s base! The names Herodwartus. I\'m the guild\'s historian. I know all about it\'s history! The Talon\'s purpose is to hunt all loyal to the Scourge and to the Burning Legion. All their leaders followed this purpose, Nicholas Othmar, to the last and now deceased Ragnar Magnus.\n\nBut, let me tell ye, fallen leaders won\'t stop the Talon from hunting all Scourge beasts and Demons of Azeroth! Now the Talon\'s being led by Arnest. He\'s dumb, but he\'ll learn! Ye\'ll see.',NULL,0,0,0,0,0,0,0,0,0),
(60899,'What brings you to Anchor\'s Edge of all places?',NULL,0,0,0,0,0,0,0,0,0),
(60900,'The Deep Tide has been a loyal vessel to Kul Tiras for many years.',NULL,0,0,0,0,0,0,0,0,0),
(60901,'Our journey has taken much longer than expected. It is about time that we bring our efforts against the Horde.',NULL,0,0,0,0,0,0,0,0,0),
(60902,'Keep your faith in the Light, and all shall reveal itself.',NULL,0,0,0,0,0,0,0,0,0),
(60916,'Long has it been since anyone has ventured to this place.',NULL,0,0,0,0,0,0,0,0,0),
(60917,'My kingdom has crumbled to dust, my subjects long gone, and my memories fading. But yet, I remain here, a haunting reminder of the greatness that once was. What brings you to my forgotten realm?',NULL,0,0,0,0,0,0,0,0,0),
(60924,'We Redbrand fought alongside the king in the War of Three Hammers ages ago. We hold a proud legacy and should not be judged lightly.',NULL,0,0,0,0,0,0,0,0,0),
(60925,'My name is Nazgrim Redbrand, Lord of the noble Redbrand family. The Redbrands have suffered many tragedies of late, with our namesake crumbling around us. I will not stand idly by and watch my family\'s legacy tarnished by misfortune.$B$BThe reputation of a dwarf means a great deal here in Khaz Modan, and so long as I stand as the head of the Redbrand family, I shall see its honor restored.',NULL,0,0,0,0,0,0,0,0,0),
(60926,'My job is to understand the enemy and to find their weak points.\n\nI could comment on the many flaws of Stormwind, but that is not why I am here.\n\nWhat is it I can do for you, $R?',NULL,0,0,0,0,0,0,0,0,0);
INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`,`chat_type`,`sound_id`,`language_id`,`emote_id1`,`emote_id2`,`emote_id3`,`emote_delay1`,`emote_delay2`,`emote_delay3`) VALUES
(60927,'Stormwind was kind enough to offer us accomodations and a place to hold our Embassy. I feel it will be quite a while until the two kingdoms see eye to eye to stand together.',NULL,0,0,0,0,0,0,0,0,0),
(60928,'This harbor ain\'t too shabby for fishing!',NULL,0,0,0,0,0,0,0,0,0),
(60929,'It can be difficult to control the rabble of sailors and the animosity between them and the marines.\n\n It is where Petty Officers like myself come in.',NULL,0,0,0,0,0,0,0,0,0),
(60930,'The Nation of Kul Tiras is generous to its loyal subjects and those that swear fealty to it.\n\nOur loyalties and dedication lay with the Kingdom of Lordaeron and the Old Alliance.\n\nWhere do your loyalties lay?',NULL,0,0,0,0,0,0,0,0,0),
(60931,'Stormwind isn\'t as bad as those in Boralus make it out to be.',NULL,0,0,0,0,0,0,0,0,0),
(60932,'You do not know the sheer pleasure of being able to stretch your legs on dry land after such a long expedition.',NULL,0,0,0,0,0,0,0,0,0),
(60933,'What can I do for you, mainlander?',NULL,0,0,0,0,0,0,0,0,0),
(60934,'I have been sent on behalf of the Lord Admiral to engage in diplomacy with our southern neighbors.\n\nI have been curious to see if the nobility here are true to the old ways, and to see what respect they hold for the fallen sister kingdoms to the north.\n\nIf Kul Tiras and Stormwind are to ever stand side-by-side then brutal truths must be laid out for all to understand bluntly.\n\nThere is no truces to be had with the Blackbloods, and no honor to be made standing alongside those that destroyed what once was.',NULL,0,0,0,0,0,0,0,0,0),
(60935,'It is not often that I get to speak with a mainlander.',NULL,0,0,0,0,0,0,0,0,0),
(60936,'The sea is harsh and filled with secrets. There is still more out there for us to explore, and more for expeditions to chart on maps.\n\nYou can count on us to find the unveiled places of this world.',NULL,0,0,0,0,0,0,0,0,0),
(60937,'I haven\'t been to Stormwind in a long time. It\'s nice to see how much it has changed.',NULL,0,0,0,0,0,0,0,0,0),
(60938,'You be standing on the Old Tide, ship of Kul Tiras, and I am the Deskmaster here.\n\nDo not cause me any issues on the boat, $C.',NULL,0,0,0,0,0,0,0,0,0),
(60945,'<The whelp looks at you curiously.>',NULL,0,0,0,0,0,0,0,0,0),
(60946,'Mmrmmgl?',NULL,0,0,0,0,0,0,0,0,0),
(60949,'We stand watch.',NULL,0,0,0,0,0,0,0,0,0),
(60950,'Oh, the things I would do for a bottle of Dalaran Red...',NULL,0,0,0,0,0,0,0,0,0),
(60951,'I hate this swamp.',NULL,0,0,0,0,0,0,0,0,0),
(60955,'The desert be rife with opportunities, and chances to gain a little coin. I represent some interests across the ocean that are looking for rare and unique goods.\n\nPerhaps we can help each other out, aye?\n\nOh, and uh, if you\'re looking for some cheddar, I got a bunch of it, they took my letter way too seriously.',NULL,0,0,0,0,0,0,0,0,0),
(60956,'Hello there, and welcome to the Steamwheedle Art Museum, make yourself right at home, and enjoy a few fine works from the community.',NULL,0,0,0,0,0,0,0,0,0),
(60960,'Can you believe the luck, the only two shredders we had working out in this neck of the woods went and broke down!\n\nNow I\'m stuck here repairing with hardly any parts to speak of.',NULL,0,0,0,0,0,0,0,0,0),
(60961,'I got sent from Sparkwater to look after this place. We got a lot of projects in the making around here, and us technicians make sure all the part kept in working order.$B$B$Anyway, what can I do for you?',NULL,0,0,0,0,0,0,0,0,0),
(60962,'Boy howdy, have you ever seen anything so magnificient, so beautiful? This baby could blow a crater the size of Sparkwater wherever we light this fuse, and its my job to make sure we don\'t blow ourselves into smithereens!\n\nOh, I anticipate the day Nazz gives the thumbs up to use this thing, it\'ll be the greatest explosion ever seen on Azeroth!',NULL,0,0,0,0,0,0,0,0,0),
(60964,'This is the last place I thought I would end up, believe me, but the goblins spend well, and I have business here.',NULL,0,0,0,0,0,0,0,0,0),
(60967,'Move it on pal, before you get me angry.',NULL,0,0,0,0,0,0,0,0,0),
(60968,'Hope you\'re enjoying the town, its much better to be working with the Durotar Labor Union then those goons at Venture Co.',NULL,0,0,0,0,0,0,0,0,0),
(60969,'Welcome to Powder Town, hope you find whatever you\'re looking for here, or are just around to help out, make yourself comfortable.',NULL,0,0,0,0,0,0,0,0,0),
(60970,'Why hello there, I got problems that need fixed, you look like someone that might be able to fix problems.\n\nPerhaps there is something we can do to help eachother out yeah?',NULL,0,0,0,0,0,0,0,0,0),
(60973,'No cause-cause trouble or me cut you!\n\nMe cut good, me cut best!',NULL,0,0,0,0,0,0,0,0,0),
(60976,'You there, yes yes, I come from swamp called Wetlands, you heard of yes yes?\n\nBig leader Gowlfang used to stay here, look for help help, but now he is fighting to become leader of Mosshide!\n\nI here to help guide people to him.',NULL,0,0,0,0,0,0,0,0,0),
(60990,'There is always adventure to be had, especially out in the far frontiers.',NULL,0,0,0,0,0,0,0,0,0),
(60991,'Welcome! Make yourself comfortable. We have plenty of ale and lodging should you need a rest.',NULL,0,0,0,0,0,0,0,0,0),
(60993,'I\'ve known Whitepeak ever since my time serving Ironforge.\n\nI\'m certain he could use my experience and expertise out here, especially so far from home.',NULL,0,0,0,0,0,0,0,0,0),
(60994,'We are far in hostile territory, practically surrounded by enemies. It is best to keep our whits about us and be ready for a fight.\n\nAre you looking to assist us here in Bael Hardul?',NULL,0,0,0,0,0,0,0,0,0),
(60996,'Kalimdor is surely to be full of rich and rare minerals that we don\'t often see on the Eastern Kingdoms and I\'m sure of it, I just need to find what I\'m looking for, that\'s all.',NULL,0,0,0,0,0,0,0,0,0),
(60997,'Welcome to Bael Hardul, this place was left here from the time of the Third War.\n\nUs dwarves contributed to help the Alliance during those times, battling against orc and demon alike until the unification and the battle at Mount Hyjal.\n\nThis place was left abandoned, we\'ve only just recently arrived to call it home for our future expeditions.\n\nWe could certainly use the help if you\'re willing to offer assistance.',NULL,0,0,0,0,0,0,0,0,0),
(60998,'I am an emissary from Stonetalon Peak, and something of a guide to help Whitepeak and his kin traverse these lands without disturbing the natural order.',NULL,0,0,0,0,0,0,0,0,0),
(60999,'I\'ve never been this far west! I\'m eager to try some of my long-delayed experiments now that I am free from scrutiny.',NULL,0,0,0,0,0,0,0,0,0),
(61000,'The life of an engineer, I thought I would be doing invention, but I mostly am a glorified mechanic helping fix broken devices and machinery.\n\nOh well, atleast I\'m working with tools.',NULL,0,0,0,0,0,0,0,0,0),
(61001,'Do you know how long that farm took to fertilize?!\n\n<The dwarf is visibly upset.>\n\nAll that preparation just for some vultures to come and ruin everything.',NULL,0,0,0,0,0,0,0,0,0),
(61004,'The Explorers\' League is always looking for help, we are often stretched too thin to carry out our motivations and goals.',NULL,0,0,0,0,0,0,0,0,0),
(61006,'The skies be calling my name but I can\'t be answering!\n\nThe bloody flying machine went and broke down, and now I\'m grounded like the rest of the peasantry.\n\nYou know a thing about Gyrocranked Fizz-wobbled engines?',NULL,0,0,0,0,0,0,0,0,0),
(61008,'Why hello there. Is there anything I can do for you?',NULL,0,0,0,0,0,0,0,0,0),
(61009,'I wouldn\'t mess with the Redbrand if I were ye.',NULL,0,0,0,0,0,0,0,0,0),
(61010,'Ours is a rich history, full of distinction and honor. We once served as the right hand to the Bronzebeards, but there have been many unfortunate incidents within the past few generations.$B$BI have been looking for assistance in collecting a number of our lost chronicles. Perhaps you could be of help?',NULL,0,0,0,0,0,0,0,0,0),
(61011,'I have been chosen as a champion of the Redbrands, to defend their kin and fight on their behalf.$B$BI suggest you do not cross them, $C.',NULL,0,0,0,0,0,0,0,0,0),
(61012,'I am solemnly sworn to defend the interests of my lord.',NULL,0,0,0,0,0,0,0,0,0),
(61013,'The south isn\'t so bad after all. Good ale, and a chance to stretch my weary sea legs from the long journey.\n\nWhat can I do for you, mainlander?',NULL,0,0,0,0,0,0,0,0,0),
(61014,'<Sailor Capewind looks over you curiously.>\n\nIs there something you need, or are you just intrigued by the tabard?\n\nNever seen an islander before?',NULL,0,0,0,0,0,0,0,0,0),
(61015,'All this money I\'ve saved up; no better time to spend it than right now, aye?"\n\n<Sailor Brewen laughs.>',NULL,0,0,0,0,0,0,0,0,0),
(61016,'You better back off before we have a problem, understood?',NULL,0,0,0,0,0,0,0,0,0),
(61017,'The ambitions and desires of Kul Tiras are a complicated matter. Our goal here is to determine the true value of these southerners and to see if mainlanders can be trusted.\n\nShould the nobility of Stormwind prove themselves loyal to the old ways and old causes, then perhaps there may be a future of cooperation.\n\nWe shall see where the heart of Stormwind is rightly at.',NULL,0,0,0,0,0,0,0,0,0),
(61019,'I drift in and out of reality, and I fear I will not remain long, you must assist me before I depart for good.',NULL,0,0,0,0,0,0,0,0,0),
(61024,'Slackers! All of them! Back in my day it was a privilege to work with that kind of firepower. Kids these da—\n\n<Nazz turns his attention towards you.>\n\nHey kid. Welcome to Powder Town! Came to rest? Then stay for the thrill! These idiotic "Engineers" Nert provided could make us blow at any minute!\n\nAnyway, got some work around here for you if you like getting your hands dirty for coin. Why else would you come to Powder Town?!\n\nOh, and don\'t worry about making yourself useful, just stay and visit. You wouldn\'t be the first anyway.\n\nNOW BEAT IT!',NULL,0,0,0,0,0,0,0,0,0),
(61026,'Water breaks upon the shore and battle draws near, you can feel it within the air, can you not young one?\n\nOur enemy has the audacity to rebuff their strength and challenge the might of the Horde head on.\n\nWar calls us, and it is up to each and every member of the Horde to answer it, will you take up the axe and defend your homeland?',NULL,0,0,0,0,0,0,0,0,0),
(61040,'<The centaur lady stares menacingly, arms folded, and tail swishing.>\n\nWho are you to speak to me? Did Warug send you?',NULL,0,0,0,0,0,0,0,0,0),
(61041,'<Dekshar stares with wild eyes.>',NULL,0,0,0,0,0,0,0,0,0),
(61044,'<The elderly centaur raises his head to speak to you.>\n\nYou are not of our tribe, yet you walk among us. What brings you here?',NULL,0,0,0,0,0,0,0,0,0),
(61045,'We are always under the threat of war, we must task ourselves for conflict, unless we be trampled like the many tribes before us.',NULL,0,0,0,0,0,0,0,0,0),
(61050,'<Daron looks somewhat confused by your presence.>\n\nNot often that we get outsiders, not in many years truthfully.\n\nWelcome either way, you need something?',NULL,0,0,0,0,0,0,0,0,0),
(61051,'What can I do for you $R?',NULL,0,0,0,0,0,0,0,0,0),
(61052,'Watch yourself buddy.\n\nWhat do you want?',NULL,0,0,0,0,0,0,0,0,0),
(61057,'Well, we\'re sure off course, took a wrong turn and ended up here.',NULL,0,0,0,0,0,0,0,0,0),
(61060,'Gizzin doesn\'t have the best sense of directions...',NULL,0,0,0,0,0,0,0,0,0),
(61063,'There is always to be a battle had in the good of nature, It is up to all of us to champion for it.',NULL,0,0,0,0,0,0,0,0,0),
(61064,'Greetings, the Kirin Tor welcomes all who wish to grow our knowledge on the arcane.\n\nIs there anything I can do for you?',NULL,0,0,0,0,0,0,0,0,0),
(61065,'There is always work to be done, we hope for a day when Dalaran is fully restored.',NULL,0,0,0,0,0,0,0,0,0),
(61070,'Hola cariño, pareces que has tenido un día difícil ¿Qué tal un caramelito de menta? ¡Porque te canta el aliento!\n\nVamos, quédate un rato y cuéntale todo a Dorothea.\n\nHey sweetie, you look like you\'ve had a rough day. How about a mint? Because your breath strinks!\n\nCome on, stay a while and tell Dorothea all about it.',NULL,0,0,0,0,0,0,0,0,0),
(61100,'Hmm, just a bit more residue to mix with the roots could potentially... Perhaps altering the growth of the tree itself-\n\nCan\'t you see that I am a bit busy, I am nearly on the cusp of a breakthrough to something magnificent can\'t you see?\n\nThe secret of the Gargantuan Banana is at my finger tips, now unless you\'re here to help move along.',NULL,0,0,0,0,0,0,0,0,0),
(61101,'You\'re sure far out, sorry if you were sent here and welcome if you came on your own accord!\n\nMy name is Bixxle, been managing this Storehouse for quite a while now. This used to be one of the primary locations of Banana collecting a while ago, but now its sort of all gone to hell.\n\nApes, monkeys, and snakes have been causing all sorts of issues, but I don\'t need to tell you that, you\'ve seen em by now!\n\nPerhaps you can help us out with some things around here, we could certainly use it.',NULL,0,0,0,0,0,0,0,0,0),
(61102,'You one of those adventurers? If so, you\'re just what I\'m lookin\' for. We\'ve had so many problems, and everything has collapsed. I got more dead employees than I do bananas, do you UNDERSTAND?!\n\n<Baron Telraz takes a moment, clearing his throat.>\n\nApologies about that, a goblin can get quite upset about the loss of so much capital and gold. Time is money, but on Tel\'Abim, time is losing money.\n\nSuch a calamity must be reversed before all of the investments here turn to nothing. I am telling you, a goblin is worth his gold, and I am not returning to Kezan with a few bananas in my pocket.',NULL,0,0,0,0,0,0,0,0,0),
(61105,'Don\'t cause any trouble around here, I got enough problem with all the apes running around lately.',NULL,0,0,0,0,0,0,0,0,0),
(61106,'Well you sure are far out from the Basecamp bub, not everyone comes all the way out to the Storehouse these days.\n\nI hope you weren\'t assigned to this heaping dung pile.',NULL,0,0,0,0,0,0,0,0,0),
(61108,'Goblin Machinery, intricate parts and haphazard design. It certainly leads to spectacular breakdowns, which is what keeps engineers like myself in business.\n\nSo, what\'ll it be?\n\nYou better not be here for Shredder repairs.',NULL,0,0,0,0,0,0,0,0,0),
(61109,'The sun sure is hot, huh?  I\'m in charge of the water and the refreshments around here, so you should be on your best behavior. Understood?\n\nOtherwise, you can get your drinks from the ocean!',NULL,0,0,0,0,0,0,0,0,0),
(61110,'Welcome to the inn here at the Tel Co. Basecamp, we are monkey free and very affordable. Please, do make yourself comfortable.\n\nAlso, I just want to dispel floating rumors that have been going around. There were no monkey attacks at this establishment. NONE AT ALL. A roving band of monkeys did NOT break in at the late hours of the night, cause a ruckus, and attack innocent patrons.\n\nIf it does happen though, we offer a free night\'s stay.',NULL,0,0,0,0,0,0,0,0,0),
(61111,'Nokrot thinks he\'s all special, but I am the one that provides him with the water he loves to wave around.',NULL,0,0,0,0,0,0,0,0,0),
(61112,'Listen here pal, sometimes you need to think outside of the box. I spent many of my days working with boring strider meat in Ratchet, and if I ever wanna make it big with a bigshot name back in Kezan, I need to use some innovation.\n\nA goblins best trait is cunning, and thinking, you see? A big brain needs big ideas and what better way to think out of the box then Tel\'abim? Bananas are the secret kid, I\'m tellin\' ya, just the right spice, the right ingredients, and it\'ll hit big.',NULL,0,0,0,0,0,0,0,0,0),
(61113,'These apes need a lesson in discipline, its about time we hit them back, and hit hard. It isn\'t all bashing though, sometimes you need strategy, and O\'ggon certainly helps when strategy doesn\'t work.',NULL,0,0,0,0,0,0,0,0,0),
(61116,'What do you want? If I were you, I wouldn\'t be sticking my nose where it didn\'t belong.',NULL,0,0,0,0,0,0,0,0,0),
(61117,'Yo $r, ever wondering what\'s hiding beneath your feet? What bounty we can claim from lost cultures? Perhaps we could find out together.',NULL,0,0,0,0,0,0,0,0,0),
(61121,'Welcome to Icepaw Village. The others will treat you with kindness in these lands.\n\nLet us join together to enjoy this Winter Veil, and perhaps spread some of the foreign food around, yes?',NULL,0,0,0,0,0,0,0,0,0),
(61122,'The snow is fresh, and the air is cool. For us Icepaw, the time begins to start our festivities, and to celebrate an end to another year.',NULL,0,0,0,0,0,0,0,0,0),
(61125,'I hope the others like my presents!',NULL,0,0,0,0,0,0,0,0,0),
(61126,'You friend with monkey, you friend with Ebu? Ebu like friend, you help, yes?',NULL,0,0,0,0,0,0,0,0,0),
(61136,'I am not that scary. Don\'t be afraid to say hello. The other yetis give us all a bad name.',NULL,0,0,0,0,0,0,0,0,0),
(61137,'I must admit, I was not expecting company. I decided to live here for such a reason infact, I enjoy being alone these days, for I have seen a lot. It has been quite a while since someone has bothered to pay me a visit, what brings you to my lonely estate tucked away within the mountain?\n\nIf you come here asking for coin, I must apologize ahead of time, I have none.',NULL,0,0,0,0,0,0,0,0,0),
(61142,'The tensions have grown in Forest Song, I feel it is only a matter of time until things get out of hand.',NULL,0,0,0,0,0,0,0,0,0),
(61143,'Why hello there outsider, and welcome to Forest Song.\n\nThis place was once a tranquil glade of our past, though now it is simply ruins. We are doing our part here to maintain the area, and to combat the Warsong Clan from gaining more of a foothold within our sacred forests. They have a lot of tenacity, and vigor, especially for Greenskins, and must be put to an end.\n\nPerhaps you can assist us, for we have many troubles, both inside, and outside.',NULL,0,0,0,0,0,0,0,0,0),
(61145,'This sacred forest yearns for reprieve from the outside forces that gnaw away at its roots.',NULL,0,0,0,0,0,0,0,0,0),
(61146,'The Kaldorei have offered me sanctuary, I have lived here for a long time, the added protection from the rest of nature is a warm welcome.',NULL,0,0,0,0,0,0,0,0,0),
(61147,'An outsider, why hello.\n\nThis glade was once revered by many druids before the Third War, it is here we communed with nature and the spirits of the forest itself. As of late, the orcs have disturbed this place of sanctuary, the burden now lays on our shoulders to help restore this place.\n\nNo doubt you have seen sentinels about, they have also added to the growing headache that is Forest Song as of late.',NULL,0,0,0,0,0,0,0,0,0),
(61149,'You stand before a great hero of the forest friend, do not disrespect the land in which you walk. Ethwyr, the treant before us sacrificed himself for the greater good of felwood. You can see the greenery, and the life all around you, it is a miracle, especially in these cursed lands.\n\nPerhaps we can learn more about his secrets, and unlock the very cleansing of the forest itself, that is why I am here.',NULL,0,0,0,0,0,0,0,0,0),
(61150,'This land was not always like this, there were many boroughs and towns all around the forest.\n\nIt is a shame to see what has become of this place, the corruption of the demonic invasion not long ago has scarred this land, we must do our best to combat it.',NULL,0,0,0,0,0,0,0,0,0),
(61151,'The wilds are fascinating, are they not? Nature has always been a mysterious guardian, with many secrets for us to uncover, and protect.\n\nMy name is Calaran, what is it you seek here friend?',NULL,0,0,0,0,0,0,0,0,0),
(61157,'Nibu looks at you curiously.',NULL,0,0,0,0,0,0,0,0,0),
(61158,'The Matron said I get to sit on Greatfather Winter\'s lap and ask him for a gift! I really would like to get my mommy back.',NULL,0,0,0,0,0,0,0,0,0),
(61159,'I\'m going to ask for a big mace! The Matron told me stories about this prince in Lordaeron that was a great paladin, I aspire to be like him!',NULL,0,0,0,0,0,0,0,0,0),
(61160,'I\'m going to ask Greatfather Winter for a totem. I wanna become a shaman just like our Warchief. For the Horde!',NULL,0,0,0,0,0,0,0,0,0),
(61161,'Lok\'tar! Zoki, the strongest warrior of the Horde welcomes you!',NULL,0,0,0,0,0,0,0,0,0),
(61168,'The Spirit gazes long into your soul, it is cold, and unwavering.',NULL,0,0,0,0,0,0,0,0,0),
(61169,'The hulking Ancient creaks as it looks upon you. You sense a caring soul being housed within the wooden mass. It urges you to move on as it seems to have a duty.',NULL,0,0,0,0,0,0,0,0,0),
(61170,'Father Bear turns to look at you for a moment before opening his mouth and speaking.>\n\nYoung one, these are dire times but remember that in the darkness there is always hope. I have brought succor to many of the bears, and yet so many have fallen to corruption. Watch yourself in these lands.',NULL,0,0,0,0,0,0,0,0,0),
(61171,'Greatfather Winter stares at you with an appreciative gaze, but his mind is clearly focused on something else. He urges you to move on with a kind fatherly gaze.',NULL,0,0,0,0,0,0,0,0,0),
(61172,'The massive Kodo stares at you for a moment before speaking in a kind fatherly tone>\n\nWinter is coming young one, you\'d best seek a warm place. I have guided tribes for generations and must continue to do so. I must depart now, I hope you will find succor in the darkness, may the Earthmother guide you to greener pastures.',NULL,0,0,0,0,0,0,0,0,0),
(61173,'Lok\'tar! Merry Winter Veil to you little $Gboy:girl;!\n\nThere is free food and lots of merriment courtesy of Smokywood Pastures!\n\nMake sure you have a splendid time... And no you may not sit on my lap.',NULL,0,0,0,0,0,0,0,0,0),
(61174,'Do not be alarmed mon. Not all Frostmane are on da warpath, we be here to celebrate.\n\nSome of us seek peace. Our tribe has suffered much, we\'re just here to celebrate the Great Spirit of Winter\'s bounty.',NULL,0,0,0,0,0,0,0,0,0),
(61175,'Do not be alarmed mon. Not all Frostmane are on da warpath, we be here to celebrate.\n\nSome of us seek peace. Our tribe has suffered much, we\'re just here to celebrate the Great Spirit of Winter\'s bounty.',NULL,0,0,0,0,0,0,0,0,0),
(61177,'Greetings Mon, ya wish to hear about the Great Spirit of Winter? It is he that ushers in the season, and brings it time for our season. The time for hunting, the time for gathering.\n\nOnce the season arrives we hold a celebration. Sacrifices, dances, rituals, and a great feast. We celebrate our survival, the changing of the season, and the end of another year on this world mon.',NULL,0,0,0,0,0,0,0,0,0),
(61178,'You wish to know about Greatfather Winter? Ah I apologize, perhaps you should speak to Storyteller Tylekinah. These are legends my people moved past, and what little I know of our ancestral beliefs tied to this tradition comes from her. I am merely here for the merriment and to share stories.',NULL,0,0,0,0,0,0,0,0,0),
(61179,'The term "Winter Veil" is said to stem from an ancestral figure known as Greatfather Winter. As he would walk the land late in the seasons, winter itself would be his billowing cloak. In his wake was the blanketing of the land in snow, and thus it is said that Greatfather Winter would cast his wintry veil over the land.\n\nAs Greatfather Winter walked the land, it is said he would provide a bounty for those who welcomed his presence. Though parts of Azeroth may lie in snow, it gives the land time for rebirth and renewal. As such, the idea of feasting during the winter veil would bring together communities as they shared whatever they had. Typically, a single day of merriment and feasting welcomed the change, all in anticipation of the land\'s renewal.',NULL,0,0,0,0,0,0,0,0,0),
(61180,'You wish to learn about our interpretation of the legend of Greatfather Winter eh?\n\nWell there\'s not much to say, we believe he is a kind old gentleman who delivers presents. It\'s never been a cultural legend as it has been for the other races, but we do share in the reveling. Plus I got some good tales from my days in the army.',NULL,0,0,0,0,0,0,0,0,0),
(61181,'Hm you wish to know about Great-father Winter? Well, in our culture... There is none. As you may know we Orcs come from another world, we do not have our own analogous story to this.\n\nAll we know is the Great-father Winter that entertains children. Greklor has quite taken to the role. Ah but never use his name before him, all the children believe he is Great-father Winter, and that\'s how it should be. I do have some good stories from Draenor to trade though.',NULL,0,0,0,0,0,0,0,0,0),
(61182,'Ah, you wish to hear about the Ancient of Winter? I come from Starfall Village located in Winterspring. It is exceptionally cold, and we are isolated from others. It is our duty to tend to the sleeping druids who must commune with the spirits of the land, even in such a cold place. During the winter the land becomes unbearably cold and harsh, even for us.\n\nThat is when we are visited by the great Ancient. The Ancient speaks to the druids in their dreams, helping them find what we need to survive. In turn we honor the Ancient with a celebration and a feast. It is thanks to the Ancient that the druids are kept safe, and a time of great renewal follows the cold winter months.',NULL,0,0,0,0,0,0,0,0,0),
(61183,'You wanna know about da ice Loa?  da, the reason for Trolls to partake? Then ya ask da Frostmane. We come from warm lands, with different Loa, each tribe be having its own traditions.\n\nWe respect all Loa, so I be here to pay my respect and enjoy the feasting and tales.',NULL,0,0,0,0,0,0,0,0,0),
(61184,'One of our oldest stories speak of the Earthmother\'s oldest son, the Winter Patriarch. As the leaves fall and the days become short, he will arrive. He brings with him great herds of game, but in turn also brings the cold and long nights.\n\nOur tribes spend these times huddled together around a fire, telling our ancestral stories while feasting. Game is difficult to hunt in these times, so we always pray to the Patriarch for a blessing that we may survive. Once the cold and gloom gives way to spring, the Patriarch departs, returning to his slumber as the land can provide for us. Only awakening once more when he is needed.',NULL,0,0,0,0,0,0,0,0,0),
(61185,'I do not have any stories that will interest you. Ask Brandon.',NULL,0,0,0,0,0,0,0,0,0),
(61186,'When it gets cold, it kinda sucks to be alone and empty stomached, yeah? How about spendin\' time with friends!\n\nGreat-father Winter has the solution. In collaboration with Smokywood Pastures, for a negligible fee he will bring wonderful presents and foodstuff, yeah? So it is a merry time of the year. Indulge and surprise each other with exotic toys, presents, and delicious food after playin\' in the snow!',NULL,0,0,0,0,0,0,0,0,0),
(61187,'Humm... When the cold sets over the land, it is said Father Bear will arrive and usher in the great sleep. Food becomes scarce, the nights long, and the cold reigns.\n\nFather Bear\'s arrival culminates in a huge feast after which many of us will enter a deep slumber, only awakening at the end of winter, when it is said that Father Bear departs. The forest and land blooms with life, food is abundant and a new renewal is upon us. Thus we celebrate this season and feast before we slumber.',NULL,0,0,0,0,0,0,0,0,0),
(61188,'Wanna know about Greatfather Winter? Heh, well our stories are similar to the Dwarven one except he rides in a Sled pulled by a huge Gyrocopter armed with missiles! You\'d probably better ask Henning if you want the details, but remember! The real one rides a sled pulled by a Gyrocopter with missiles!.',NULL,0,0,0,0,0,0,0,0,0),
(61189,'Hello to you $r! I am a scholar tasked with studying the legends surrounding these festivities. Don\'t you find it peculiar how so many separate cultures have a similar figure?',NULL,0,0,0,0,0,0,0,0,0),
(61214,'Ishnu-alah, dreamer, and welcome to our concealed enclave. May it provide some respite from the long journey ahead into the Emerald Nightmare.',NULL,0,0,0,0,0,0,0,0,0),
(61216,'The Emerald Dream is within our reach, dreamer.',NULL,0,0,0,0,0,0,0,0,0),
(61217,'Yauur?',NULL,0,0,0,0,0,0,0,0,0),
(61254,'Why hello there, not often I get visitors in the Opera Hall.$B$BYou want to hear any music? It\'s been a while since I have had the chance to test my skills in this place, with the lack of people and all. I promise you it will be great, I am a famous musician after all.',NULL,0,0,0,0,0,0,0,0,0),
(61255,'Why hello there, and welcome to the festivities. I apologize for the other guests not treating you with proper decency. It would appear they are quite... ravenous these days.$B$BI am Lord Ebonlocke of Darkshire. I traveled here of my own accord and have not returned since. I am quite aware of my current state in the tower, for I have been dead for some time. Most others that linger here are not as keen, unfortunately. It would appear that I am cursed to haunt these halls until something most fortuitous should free me from this eternal confinement.$B$BPerhaps we can help one another. I have come to learn a few things and meet others in a similar situation to mine during the time I have been bound here.',NULL,0,0,0,0,0,0,0,0,0),
(61256,'<The apparition seems preoccupied, lost in thought, and lingering in time.>',NULL,0,0,0,0,0,0,0,0,0),
(61257,'It shall always be a Greymane who sits atop the Gilnean throne. It is by the will of my Lord that this will come to pass once again.$B$BI admit, I have little trust in outsiders, but I realize such attitudes have doomed us to these times we live in.',NULL,0,0,0,0,0,0,0,0,0),
(61258,'Welcome to my lighthouse.$B$BI should warn you, I may not have the most welcoming accommodations. I simply keep the fire burning to guide ships from hitting the shoal.$B$BWhat brings you here, anyway?',NULL,0,0,0,0,0,0,0,0,0),
(61260,'The Kirin Tor called Arugal a charlatan using cheap parlor tricks to pass for a mage. If only they could have understood his genius and mine.$B$BThe so-called Worgen curse is a blessing: With Arugal\'s research, we can achieve immortality, never again to fear sickness or frailty, empowered as we are with strength beyond human comprehension.$B$BWe have yet to test the curse on races other than humans and dwarves, but we are not so depraved as to force it upon those unwilling.',NULL,0,0,0,0,0,0,0,0,0),
(61265,'The Gilnean Brigade has finally returned home. We are here to reclaim these lands in the name of Greymane.',NULL,0,0,0,0,0,0,0,0,0),
(61269,'Why, hello there, and welcome to Ravenshire!$B$BThis storied town is one of the oldest in Gilneas, and has long pledged fealty to the lords of Ravenwood Keep.$B$BSince the castle fell under dark times, Lord Ravenwood has relocated his court here, which means that history is being made right before our eyes!$B$BIf you\'d like to learn more of our fascinating past, I have quite the collection of texts that range from historical accounts and scholarly dissertations, to thrilling folktales and fables.',NULL,0,0,0,0,0,0,0,0,0),
(61270,'I must admit, it feels weird to not be within Gilneas City, especially with so much chaos. I once held the council of the king, and now look at me, groveling in Ravenshire of all places.$B$B<A sigh escapes the Magistrate.>$B$BPerhaps this will all be worth it in the end, once this conflict is over and the land begins to heal.',NULL,0,0,0,0,0,0,0,0,0),
(61271,'With the Greymane displeasure for the Kirin Tor I never expected to be here within Gilneas helping the people.$B$BThese are strange times, full of strange events. I am here to offer my assistance, and act as an envoy from the City State of Dalaran.$B$BDo you have business with the Kirin Tor?',NULL,0,0,0,0,0,0,0,0,0),
(61272,'I am sure you will find something you\'re looking for.',NULL,0,0,0,0,0,0,0,0,0),
(61273,'I can assure you, Gilneas is known for its craftsmanship.',NULL,0,0,0,0,0,0,0,0,0),
(61274,'Ravenshire has relied on fish for quite a while, and the ocean is always bountiful enough to feed.',NULL,0,0,0,0,0,0,0,0,0),
(61275,'What you want outsider?',NULL,0,0,0,0,0,0,0,0,0),
(61276,'My father has been teaching me how to craft and repair armor for pretty much all of my life. If you\'re ever wanting to learn a thing or to, you should speak with him, he certainly is the best.',NULL,0,0,0,0,0,0,0,0,0),
(61277,'My son likes to exaggerate, but he is a hard worker. If you\'re looking to be a skilled blacksmith, you need to work hard at it to succeed.',NULL,0,0,0,0,0,0,0,0,0),
(61278,'My job and my father\'s before me has been to hunt the local game of the region. It is honest work, but at times quite dangerous.',NULL,0,0,0,0,0,0,0,0,0),
(61279,'My father is a skilled hunter, he is able to kill giant wolf and then make them into food!',NULL,0,0,0,0,0,0,0,0,0),
(61281,'During my life it was I who looked after this church. I was murdered in cold blood by those that bear the emblem of this kingdom. It appears that I have been awoken from my slumber to serve a new purpose, and serve this purpose I shall.$B$BYou will find no hostilities here, I may be Gilnean but I offer a chance to find solace inside the walls of my parish.$B$BShould you need to rest, feel free to ask.',NULL,0,0,0,0,0,0,0,0,0),
(61282,'We have been sent to monitor the situation in Gilneas, things here are... Far more interesting than I would have imagined.$B$BPerhaps we can be a more instrumental part of future history.',NULL,0,0,0,0,0,0,0,0,0),
(61283,'The land of Gilneas is certainly wounded and scarred, but it is not rotten from the inside out like Tirisfal. Any chance to extend our influence here will take considerable effort.',NULL,0,0,0,0,0,0,0,0,0),
(61284,'Why are you staring? Have you never seen a soldier before?',NULL,0,0,0,0,0,0,0,0,0),
(61285,'Dark magic flows through my veins, I am reinvigorated to stand once more. My life was mired with deceit, anguish, and murder, perhaps now I can enact these miseries on those that wrought me to an early grave.',NULL,0,0,0,0,0,0,0,0,0),
(61286,'Can you believe it, the Scourge, here in Gilneas! No matter where I travel their taint seems to be present.$B$BThe Greymane wall was breached some time in the past. From my studies these are the remnants of a former scourge invasion. This is a good opportunity, foolish to waste. There is still much we can learn from these lands, and I must uncover all that I can while I have the opportunity.',NULL,0,0,0,0,0,0,0,0,0),
(61287,'You can\'t just sneak up on people you know that?! You almost put me into my second grave.$B$BCan\'t you see that I am occupied here? Busy, engaged, distracted, preoccupied, immersed, absorbed, working?$B$BHow many other ways can I describe this to you before you understand.',NULL,0,0,0,0,0,0,0,0,0),
(61288,'Looking for something? You\'d better spit it out.',NULL,0,0,0,0,0,0,0,0,0),
(61289,'I had always wondered what this place looked like beyond the wall... Now that I\'ve been there I must admit I am disappointed. Perhaps once you have seen one kingdom you\'ve seen them all$B$BYou looking to do some work around here, or just admire the scenery?',NULL,0,0,0,0,0,0,0,0,0),
(61290,'These damn pests, how am I ever to recover if I cannot even manage to deal with all of these issues on my own farm? The Ebonmere family was once a wealthy part of Gilneas, and now look at it, overgrown, and festering away.',NULL,0,0,0,0,0,0,0,0,0),
(61291,'You need something fixed? It would appear that is all I am good for in this new life.',NULL,0,0,0,0,0,0,0,0,0),
(61293,'So, there I was, the Silithus Desert, Hundreds of miles from the Civilization. No food, no water. But I Basutei a Paladin of SQUAD must push forward to fulfill the Prophecy... Man, this hill is kicking my Ass!',NULL,0,0,0,0,0,0,0,0,0),
(61298,'Watame did nothing wrong!',NULL,0,0,0,0,0,0,0,0,0),
(61303,'Ah, welcome, weary traveler! It is good to see you on Thunderhorn Peak. Evil stirs within Azeroth, and the times ahead are troublesome, but we can be assured that daring adventures help the ailing Earth Mother and soothe her pain. Ambassador Boughshadow is also working ever so hard to help new members of the Alliance find their place here within our ranks. Anyone willing to heal the Earth Mother is welcome.',NULL,0,0,0,0,0,0,0,0,0),
(61307,'Here lie our fallen mortal heroes of Azeroth. May their souls rest in peace.',NULL,0,0,0,0,0,0,0,0,0),
(61313,'<Muffled speech.>',NULL,0,0,0,0,0,0,0,0,0),
(61320,'These dark hallways hold more than meets the eye. Keep your wits about you, unless you want to end up walking this place for an eternity.',NULL,0,0,0,0,0,0,0,0,0),
(61321,'In my lifetime I committed all manner of crime under the guise of justice. I took bribes, laundered gold through the treasury, and did all manner of evil to gain my position.$B$BIf I could start again I would, but now I am stuck to forever think about what could have been, and what wrong roads I have taken in my short life.',NULL,0,0,0,0,0,0,0,0,0),
(61322,'Do you hear that, the incessant howling of the wind? Has someone left a window open?!$B$BFetch for a servant immediately, and fix this damned racket.',NULL,0,0,0,0,0,0,0,0,0),
(61323,'You know what the biggest shame about being a wandering spirit is?$B$BI would say it is the lack of fine food and drink. I suppose the company is lacking as well, perhaps you can change things around here.',NULL,0,0,0,0,0,0,0,0,0),
(61325,'The Emerald Dream and Nordrassil are linked together, the land itself is enchanted by the magic of that realm. Dream Shards are evidence of this, a powerful substance of pure emerald energy which can only be found here, in Hyjal.$B$BIt is my duty to harmonize Small Dream Shards into Bright Dream Shards, if you come along any in your travels, seek me out.',NULL,0,0,0,0,0,0,0,0,0),
(61326,'Hidden beneath the veil, a great shadow lurks within the dream, already much of my kind have been disturbed by the presence.$B$BYou may not know this, but the awakening has begun.$B$BAn ancient ritual of my kin intended to draw us from the dream, I have resisted its temptations already, but not all are willed so strong.',NULL,0,0,0,0,0,0,0,0,0),
(61327,'We must always prepare our stockpiles, for demons encroach upon Hyjal day after day. If their goal is to attempt to corrupt Nordrassil, we shall be ready to deny them.$B$BWhat can I do for you $c?',NULL,0,0,0,0,0,0,0,0,0),
(61355,'I hope you have come to find refuge here beneath Nordrassil, for not all wildlife is as lucky as we are.$B$BThe encroachment of darkness that has threatened this land since the Third War still lingers, do not let the beauty of the World Tree blind you to this.',NULL,0,0,0,0,0,0,0,0,0),
(61368,'Need repairs or smithin\' supplies? If so, I am your guy... For a price, of course.',NULL,0,0,0,0,0,0,0,0,0),
(61369,'Since you\'re helping us, I don\'t mind helping you resupply. Nothing\'s free, of course. This ain\'t a charity.',NULL,0,0,0,0,0,0,0,0,0),
(61371,'Hey, everyone\'s gotta eat, am I right? Well, anyone who is alive that is. In any case, if you\'re hungry, I can spare some of our stash. You better have gold on you though.',NULL,0,0,0,0,0,0,0,0,0),
(61373,'An outsider, huh? We haven\'t had those in such a long time. With the Greymane Wall closed, we haven\'t heard much of the goings-on outside the kingdom.$B$BPerhaps you can share a story or two sometime.',NULL,0,0,0,0,0,0,0,0,0),
(61374,'Glory to the Dark Lady, $c. What do you need?',NULL,0,0,0,0,0,0,0,0,0),
(61375,'Finally the Dark Lady sends some competent assistance. Do not be so surprised about my appearance. Yes, this body lives, but I am fully committed to the Horde and the Dark Lady.',NULL,0,0,0,0,0,0,0,0,0),
(61376,'If the boss says you\'re good, then who am I to judge? I for one am not a fan of this land. So I\'d prefer if we could finish our business and skedaddle as soon as possible.',NULL,0,0,0,0,0,0,0,0,0),
(61377,'I\'ve seen it all the past four years. As long as I get some good loot, I don\'t care who I work for. Now, are you here to make yourself useful to the boss or what?',NULL,0,0,0,0,0,0,0,0,0),
(61378,'Well, this is a fine day here in Gilneas, isn\'t it? Take care if you leave town, alright?',NULL,0,0,0,0,0,0,0,0,0),
(61379,'Well, this is a fine day here in Gilneas, isn\'t it? Take care if you leave town, alright?',NULL,0,0,0,0,0,0,0,0,0),
(61381,'The Shademore\'s have been extremely generous with their support, but I am afraid it isn\'t doing much to quell my worries.',NULL,0,0,0,0,0,0,0,0,0),
(61382,'Gilnean cooking is some of the finest in the world, though not all will find our ingredients enjoyable.',NULL,0,0,0,0,0,0,0,0,0),
(61383,'I have seen enough in my life to know what is right and what is wrong. It is my belief that the king has taken his matters much too far.$B$BI was once part of the Greymane cause. I now know the truth of the lies I was told.',NULL,0,0,0,0,0,0,0,0,0),
(61384,'What a time for the wheel to go loose, huh? I must say, you\'re a sight for sore eyes.',NULL,0,0,0,0,0,0,0,0,0),
(61385,'Why hello there, and welcome to Shademore Tavern. Guests are somewhat infrequent these days, but we are still happy to have you.$B$BMake yourself at home. If you need anything, come and see me.',NULL,0,0,0,0,0,0,0,0,0),
(61386,'It is hard to spread the word of the Light these days, especially with such troubled minds.$B$BI am sure such hard times will pass before long.',NULL,0,0,0,0,0,0,0,0,0),
(61387,'I am here to do my part on behalf of the Scarlet Crusade.$B$BIf you have the will to recover Lordaeron from the clutches of death and vile taint, speak with me, and perhaps you can be of use.',NULL,0,0,0,0,0,0,0,0,0),
(61416,'Why hello there, you wouldn\'t mind helping out a dwarf in need would ye?',NULL,0,0,0,0,0,0,0,0,0),
(61428,'There\'s so much work to be done around here, it\'s enough to make my head explode!',NULL,0,0,0,0,0,0,0,0,0),
(61429,'There is still a lot of work to do if we ever want to reclaim our home in Gnomeregan. Even so, it\'s an honor to be a part of the reclamation efforts!',NULL,0,0,0,0,0,0,0,0,0),
(61430,'Why hello there! Come to see a marvel of Gnomish Engineering? Perhaps you\'re just here to witness the latest and greatest technological advancements?',NULL,0,0,0,0,0,0,0,0,0),
(61433,'What\'s that? Are you the new chemist that was sent to help us out here?$B$BUnless you know something about thermal energy and toxic chemical reduction, I would ask you to move along.',NULL,0,0,0,0,0,0,0,0,0),
(61434,'A little extra hydrogen and we should be closer to a more stable...$B$BOh, you caught me off guard! What are you doing here anyway? Trying to steal my trade secrets?!',NULL,0,0,0,0,0,0,0,0,0),
(61435,'I took a lengthy trip around the world after the collapse of Gnomeregan.$B$BWith all the news of this facility buzzing about, I returned to offer my assistance where needed.',NULL,0,0,0,0,0,0,0,0,0),
(61436,'We\'re making tremendous strides here! It just so happens I am approaching a breakthrough with a new chemical purifying process that will allow us to filter the radiation without dispersing it out into Dun Morogh.$B$BThe thought alone of such a groundbreaking refinement process makes me giddy with excitement! Imagine the countless applications! There are still a few pieces to the formula missing, though...',NULL,0,0,0,0,0,0,0,0,0),
(61437,'I am in charge of every aspect of the equipment and infrastructure here in the Reclamation Facility. I know the exact location and function of every last wire and pipe that runs through these walls.$B$BWithout me, this whole place would fall apart! Who else here has any clue how to maintain the instruments and operate the panels correctly?!',NULL,0,0,0,0,0,0,0,0,0),
(61438,'Engineering is an essential foundation of Gnomish society. Without it, can you imagine where we would be?$B$BProbably still banging sticks together like some sort of troggs!',NULL,0,0,0,0,0,0,0,0,0),
(61440,'Looking for something specific? Things are a bit hectic around here, but I am sure I have what you need.',NULL,0,0,0,0,0,0,0,0,0),
(61441,'There is so much maintenance work of late. These old machines have been dormant for quite a while, and have only recently been turned on!$B$BI used to do regular checkups on this facility\'s equipment back before the Gnomeregan incident.$B$B<Weezan lets out a small laugh.>$B$BIt\'s a good thing I did! I\'m glad we thought ahead and built everything here as a backup!',NULL,0,0,0,0,0,0,0,0,0),
(61442,'There is nothing some good gnomish ingenuity cannot fix. It won\'t be long until we\'re moved back into Gnomeregan.',NULL,0,0,0,0,0,0,0,0,0),
(61444,'We have a backup of extra supplies stored if you are planning to buy in bulk today!',NULL,0,0,0,0,0,0,0,0,0),
(61445,'The goblins like to claim they are the best at making things explode, but I disagree.$B$BWithout the accuracy of intricate and delicate parts, there can be no concise direction of channeled power. What fun is blasting something without being precise?',NULL,0,0,0,0,0,0,0,0,0),
(61446,'My, you wouldn\'t happen to have a spare spanner would you, I seem to have misplaced mine.',NULL,0,0,0,0,0,0,0,0,0),
(61447,'Many may see the worgen curse as a horrible affliction, but we embrace it. We welcome it as a blessing, as it makes us stronger, faster, and longer-lived! Her name is Rosenberg, and she has saved us from a dull and ordinary life.',NULL,0,0,0,0,0,0,0,0,0),
(61448,'Much is yet to be learned of these Pellars—previously believed to be a myth, but now proven otherwise. They may be Gilneas\' roots we never knew were there. And as one meant to protect this country\'s legacy, I must learn whatever I can from them.',NULL,0,0,0,0,0,0,0,0,0);
INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`,`chat_type`,`sound_id`,`language_id`,`emote_id1`,`emote_id2`,`emote_id3`,`emote_delay1`,`emote_delay2`,`emote_delay3`) VALUES
(61449,'If ever be you needing help with fixing your gear, I know how to mend most things that break. If not, you could always sell your scraps to old Mustang.',NULL,0,0,0,0,0,0,0,0,0),
(61450,'The Wolf Serpent sees through me, hears through me, feels through me. I am the thunder of his voice, the instrument of his judgement.$B$BFor as long as you linger in the Wolfswood, you shall abide by my word.',NULL,0,0,0,0,0,0,0,0,0),
(61452,'We are the Pellars. And order of faithful guardians of the land and its children. Healers, shepards and teachers,$B$BWe see beyond the mirages of politics to aid those in Gilneas who find refuge in the old ways. Farmers, huntsmen, humble folk who did not lose their true self in the groves of stone.$B$BJoin us, return to your roots.',NULL,0,0,0,0,0,0,0,0,0),
(61454,'Have you coin, have you gold? For a copper and a silver, roots and blooms, flowers and shrooms, and yet bulbs from the dell to you I\'ll gladly sell.',NULL,0,0,0,0,0,0,0,0,0),
(61455,'<The man stares at you with a look of intensity.>',NULL,0,0,0,0,0,0,0,0,0),
(61457,'It is not the absence of liberty that holds me, stranger, but the heavy burden of my guilt. The decay of these lands at the hands of heretics has left a blight on my spirit. I have lost my parents, my title, and my freedom. Despite the darkness I bear, I still find hope in my sister, in my countrymen, and now in you.',NULL,0,0,0,0,0,0,0,0,0),
(61458,'You have given me back my freedom and, with it, the hope necessary to push on. I am no fool, nor are the men who remain loyal to our cause. Though the day may come that I must secure our future, rest assured that I will do so.',NULL,0,0,0,0,0,0,0,0,0),
(61459,'Another one of you aimless outlanders wandering up here. I wonder what exactly you\'re hoping to find.',NULL,0,0,0,0,0,0,0,0,0),
(61460,'I would love to see the final version of Ur\'s research, but unfortunately his final books are not in our possession. We must settle for his messy, half-finished ideas and notes instead. His works may make little sense now, but perhaps Moranna can see what we cannot.$B$BIn the meantime, we will provide as much aid as we can to those in need, as she did for us - the Lupine Coven.',NULL,0,0,0,0,0,0,0,0,0),
(61467,'A new era is upon us thanks to the hard work and brilliance of Gnomekind! Many of us who once dwelled here in Tinker Town have begun to gravitate back toward Gnomeregan. Well, the Reclamation Facility anyway. It\'s a new venture to reclaim our irradiated home.$B$BYou see, it was built before the betrayal of Thermaplugg and is now being used to cleanse the toxic gases from the city. Fascinating stuff, isn\'t it?!$B$BIf you\'re looking for any of the Gnomish leadership, you can find them there. Head west of Ironforge towards the entrance of Gnomeregan. You shouldn\'t have a hard time spotting the entrance.',NULL,0,0,0,0,0,0,0,0,0),
(61485,'Looking to gain rewards for your efforts here beneath the blessing of Nordrassil? If that is the case, you have come to the right person.',NULL,0,0,0,0,0,0,0,0,0),
(61486,'Time is money, friend, and my time is very valuable.$B$BGivin\' we both have better things to be doing, how about you tell me what business you have here? Keep your eyes off the coinage. Understand?',NULL,0,0,0,0,0,0,0,0,0),
(61491,'The secrets of Dreamsteel are elusive to even the most skilled blacksmiths. Do you have the potential to harness such technical precision and ability?',NULL,0,0,0,0,0,0,0,0,0),
(61492,'Clear your mind, steady your hand. There are talents that you must master if you desire to begin weaving with Dreamthread. The properties of the material are extremely unique and almost tranquil to work with.$B$BI hope you are not just here to disturb me. What is it you need?',NULL,0,0,0,0,0,0,0,0,0),
(61493,'You\'ve come to see my work with Dreamhide? I\'ll warn you, this material is not for the faint of heart. The most skilled leatherworkers have tried and failed to work with this elusive leather.$B$BMaybe you have the dedication and focus needed to master this material.',NULL,0,0,0,0,0,0,0,0,0),
(61494,'My heart yearns to return to the dream. It calls me, and desires my presence, but I am a loyal servant of Ralathius. I am bound to service until my duties here in Hyjal are complete.$B$BAside, what could I do alone anyway? Look at me, I\'m small!',NULL,0,0,0,0,0,0,0,0,0),
(61496,'I always feel at ease here within Starfall Village.',NULL,0,0,0,0,0,0,0,0,0),
(61497,'What is it you have come to search for here beneath the World Tree? Knowledge, power?',NULL,0,0,0,0,0,0,0,0,0),
(61505,'I am charged with managing our supplies of rare potions and elixirs.$B$BI was taught by the most talented druidic alchemist years ago, and work to continue his vast research.',NULL,0,0,0,0,0,0,0,0,0),
(61506,'The Barkskin Tribe has been lost to aggression. The corruption of Hyjal has taken a toll on my people, and we are all that is left here. It would appear that our sad and tragic downfall is common amongst the other tribes as well.',NULL,0,0,0,0,0,0,0,0,0),
(61507,'Nargg is loyal, Nargg is strong!$B$BYou threaten Elder Barkmaw, Nargg threaten you! You hurt Elder Barkmaw, Nargg hurt you!',NULL,0,0,0,0,0,0,0,0,0),
(61509,'The downfall of the Barkskin is a devastating loss to us Furbolg. As time passes, I fear we may be the only tribe to withstand the growing corruption.$B$BI have come representing the Timbermaw seeking to bring all those uncorrupted into our fold. If that is not possible, offer council to prevent madness from becoming rampant.',NULL,0,0,0,0,0,0,0,0,0),
(61512,'My duty is to ensure the roots of the World Tree recover from the devastation wrought by the Burning Legion. It has been some years since their leader was defeated by Malfurion Stormrage, and yet their kind still linger.$B$BAs long as you remain an enemy to demons, you will always be welcome in Nordrassil Glade.',NULL,0,0,0,0,0,0,0,0,0),
(61513,'Who...? Who goes there?',NULL,0,0,0,0,0,0,0,0,0),
(61519,'The attunement of sigils is a lost art. There are a spare few of us left in the world. It is said this ancient tradition was first started by our Highborne brethren long ago as a means to infuse ley energy into powerful enchantments.',NULL,0,0,0,0,0,0,0,0,0),
(61520,'Do you feel it? Something foul is lingering upon the air here within Hyjal.',NULL,0,0,0,0,0,0,0,0,0),
(61521,'It was in this very glade that the Alliance and Horde stood together in unison to defeat the Burning Legion.$B$BSuch an action speaks to the sheer power when politics and old feuds are set aside for the betterment of our world.',NULL,0,0,0,0,0,0,0,0,0),
(61522,'Mount Hyjal is a sacred place. Be sure to respect it.',NULL,0,0,0,0,0,0,0,0,0),
(61528,'This glade is hallowed ground. It is my task to watch over it, and protect it until my final moments.',NULL,0,0,0,0,0,0,0,0,0),
(61529,'If it is expertise in the ranged mastery of the bow you seek, you have come to the correct place $c.',NULL,0,0,0,0,0,0,0,0,0),
(61530,'Please, make yourself at home.$B$BThere is great harmony found beneath the shade of Nordrassil.',NULL,0,0,0,0,0,0,0,0,0),
(61531,'The draw of the Emerald Dream is intense. The emanations of the awakening make it even more difficult to keep on task.',NULL,0,0,0,0,0,0,0,0,0),
(61534,'Remember to be careful walking these roads. Dark times have arrived in Gilneas, and only through vigilance can it be restored.',NULL,0,0,0,0,0,0,0,0,0),
(61535,'I expected Gilneas to be a safe haven for us refugees. I never imagined it would be as bad as Silverpine Forest.',NULL,0,0,0,0,0,0,0,0,0),
(61536,'It takes a lot of thinking to make a limited amount of food last for a large group of people.$B$BSawdust can be used to thicken or increase portions of food.',NULL,0,0,0,0,0,0,0,0,0),
(61537,'Did you hear that?!',NULL,0,0,0,0,0,0,0,0,0),
(61539,'Welcome to Ravenshire. We are accommodating to the plight of those affected by the tyranny of Greymane.',NULL,0,0,0,0,0,0,0,0,0),
(61540,'We once served Gilneas with great pride. It is an odd feeling to be fighting against the powers that hold it hostage.',NULL,0,0,0,0,0,0,0,0,0),
(61559,'The phantom seems lost in time.',NULL,0,0,0,0,0,0,0,0,0),
(61560,'It is my duty to ward Hyjal from the evil that lurks beyond.',NULL,0,0,0,0,0,0,0,0,0),
(61561,'The summit of Hyjal truly is a sight to behold.',NULL,0,0,0,0,0,0,0,0,0),
(61562,'We must do our part to fight the corruption lingering in Hyjal.',NULL,0,0,0,0,0,0,0,0,0),
(61563,'Climbing the mountain to Nordanaar has become more dangerous as of late. I would advise caution.',NULL,0,0,0,0,0,0,0,0,0),
(61568,'What is it that you require?',NULL,0,0,0,0,0,0,0,0,0),
(61570,'I am afraid I cannot entertain guests. I am currently busy with my studies.',NULL,0,0,0,0,0,0,0,0,0),
(61571,'Welcome to Karazhan!$B$BI am afraid the master of the tower is currently away on business, and is not expected to return for some time. Please, make yourself at home, and enjoy our hospitality.',NULL,0,0,0,0,0,0,0,0,0),
(61572,'I have come to offer my assistance in these dark lands. Though I have found nothing but the twisted evil of rot and decay.',NULL,0,0,0,0,0,0,0,0,0),
(61574,'Me sick of fighting, no want no violence.$B$BNo fight, me sell-sell!',NULL,0,0,0,0,0,0,0,0,0),
(61576,'There is much to learn and discover in this world. Make sure your eyes and ears are open.',NULL,0,0,0,0,0,0,0,0,0),
(61577,'Greetings $r. I am Annesastrasza of the Red Dragonflight. I have been sent here to protect the world tree from those who would abuse its power. Although a lot of the energy from Nordrassil was expended when Archimonde was defeated, more still remains.$B$BRemnants of Archimonde\'s forces continue to intrude upon the mountain as they plot to capture the tree. My people are the protectors of Life, and the fall of the world tree to demons would be catastrophic for all, it might even bring the Legion back. Should you learn anything pertaining to this matter, let me know.',NULL,0,0,0,0,0,0,0,0,0),
(61578,'I be Trak\'nal, Shadowhunter of the Shadowtooth tribe. My duty to protect our ancestral home remains in spite of these difficult times. These demons will fall by my blade, as will anyone endangering the mountain. You be delaying the killing. What do you want?',NULL,0,0,0,0,0,0,0,0,0),
(61579,'Hello! Please be quiet, it is important that the demons don\'t take note of me. It is my duty to keep an eye on them. Can I help you somehow?',NULL,0,0,0,0,0,0,0,0,0),
(61580,'Hi! You seem very capable $r! Welcome to Hyjal! I wish the mountain was in a better state, but we are doing our best. Show your respect while here, alright? It\'d be inconvenient if I had to kill you.',NULL,0,0,0,0,0,0,0,0,0),
(61581,'The wardens are a dying order, one that has seen better days. That, however, will not stop me from doing my duty. These cretins encroach and defile our sacred mountain. The punishment for this transgression is death, and I intend to duly deliver it, with or without help. Now, what do you want?',NULL,0,0,0,0,0,0,0,0,0),
(61583,'An outsider approaches.$B$BWelcome to Thalanaar. I am Commander Anashya Starfall.$B$BI have been banished by my own General for what she considers insubordination, though she clearly underestimated the loyalty of my squad. Now we find ourselves here, cast aside by our own leaders who have lost sight of what truly matters - the safety of our people and the preservation of our ancestors\' legacy.$B$BFor millennia, the Night Elves have held dominion over these lands, and we shall continue to do so until the end of time. Do I make myself clear?$B$BExcellent. Let us proceed.',NULL,0,0,0,0,0,0,0,0,0),
(61584,'Feralas, a land of unrivaled beauty, remains as one of the last sanctuaries of untamed nature in the southern Kalimdor. Come, immerse yourself in its magnificence and sense the ancient tales of our kin.$B$BAlas, these territories have been abandoned for far too long and have now fallen prey to those who seek to obliterate our heritage and fade it into oblivion.$B$BI have been summoned here to reclaim what rightfully belongs to us and I shall not rest until it is done. Perhaps, fate will guide you to aid me in this noble cause.',NULL,0,0,0,0,0,0,0,0,0),
(61585,'Greetings, $r. I regret that our meeting takes place in such unfavorable conditions. These lands are far from hospitable, and despite what the druids may suggest, I find the melodious bird songs of Ashenvale preferable to the relentless downpours of this untamed jungle or the parched gusts of Thousand Needles.$B$BMight I ask what brings you to this place? If you seek to discuss our current circumstances, I implore you to abstain. This matter concerns the Sentinels exclusively, and it will be addressed by Sentinels alone.',NULL,0,0,0,0,0,0,0,0,0),
(61586,'No matter how far I retreat from the trappings of civilization, it appears that its grasp is unyielding, relentless in its pursuit.$B$BSpeak your mind, and never come back.',NULL,0,0,0,0,0,0,0,0,0),
(61587,'Listen well, traveler. My brother may choose to be a pawn in Fandral\'s game, but I am no puppet of the archdruid. I came to these lands to safeguard my younger kin from any perils that may cross his path, and from the gaze of those Sentinels. Always watching…$B$B<Bethelon chuckles and gives a playful wink to one of the Sentinels nearby, causing her to blush and hastily avert her gaze.>$B$BBut enough about them. Know this, I care not for politics, and to be frank, I am weary of its machinations. My foremost allegiance is to the natural world, and I am its willing servant.',NULL,0,0,0,0,0,0,0,0,0),
(61588,'Hail, weary traveler. You have ventured far to reach this secluded vale. Though it may appear desolate and in ruins, do not be deceived. This vale was once a place of great importance, a vital stronghold in the defense of our people.$B$BIt is now my solemn duty to restore it to its former glory, to bring new life to these crumbling monuments and to train a new generation of chimaeras to defend the people of Kalimdor.$B$BBut I cannot do it alone.',NULL,0,0,0,0,0,0,0,0,0),
(61590,'It is exciting to train under the guidance of such an experienced mentor. While he may seem harsh at times, it is only because he knows that the lessons he teaches are vital. Chimaeras are vicious creatures, and one mistake can be the difference between life and death.',NULL,0,0,0,0,0,0,0,0,0),
(61591,'These lands serve as a stark reminder of what would occur if the Burning Legion were granted a foothold in our world.',NULL,0,0,0,0,0,0,0,0,0),
(61592,'I have been sent here by Fandral Staghelm to investigate and study Ethwyr\'s sacrifice. What has transpired here holds hope not only for Felwood but also for the lands beyond.$B$BIf we can uncover the means to halt the effects of Fel Moss, the future for the Kaldorei will shine brighter than ever before. I advise you not to interrupt me, for there will be grave consequences if you do.',NULL,0,0,0,0,0,0,0,0,0),
(61607,'My duty is to ensure the safety of our armory. I can also reward those who have been extremely helpful here with powerful armor and weapons.',NULL,0,0,0,0,0,0,0,0,0),
(61610,'It is my duty to watch over this church, and the land that it inhabits.$B$BI must warn you, stay away from the crypt. It has fallen to a great darkness.',NULL,0,0,0,0,0,0,0,0,0),
(61614,'I have come here to seek support of the Nobles of Stormwind. It is a harder task than I had anticipated.',NULL,0,0,0,0,0,0,0,0,0),
(61616,'If you\'re looking to make a name for yourself, Blood Ring is just the place.',NULL,0,0,0,0,0,0,0,0,0),
(61621,'Welcome to Buckle Up! Excuse the mess, I am converting my armor shop into something new; belt buckles! If you got the yearning to create something unique, you\'re in the right place.',NULL,0,0,0,0,0,0,0,0,0),
(61622,'You there, looking to stand out among the crowds? I got plans for the creation of belt buckles. With them, you\'ll stand out like never before.$B$B<A sigh escapes Tanovan.>$B$BLook, help me out, I\'m in need of some silver, alright?',NULL,0,0,0,0,0,0,0,0,0),
(61623,'The skies of Kalimdor are as untamed as its lands. Where would you like to fly to?',NULL,0,0,0,0,0,0,0,0,0),
(61624,'Have you ever held a crossbow before, let alone shot one? It does have a bit of a kick to it.',NULL,0,0,0,0,0,0,0,0,0),
(61625,'Hello there, what can I do for you?',NULL,0,0,0,0,0,0,0,0,0),
(61626,'Your skill with a bow can be the difference between survival and death.$B$BRemember to keep training, even when you think you know it all.',NULL,0,0,0,0,0,0,0,0,0),
(61627,'The untamed wild may seem like a taunting foe. Once you learn its habits inside and out, it is simply just another potential enemy.',NULL,0,0,0,0,0,0,0,0,0),
(61628,'I am often employed to train recruits to the Stormwind Guard in how to wield bows and crossbows. For the defense of the city, or for use in battle.$B$BLet me tell you, it\'s one of the tasks I enjoy least.',NULL,0,0,0,0,0,0,0,0,0),
(61629,'To be one with nature, and to tame beasts themselves, is a skill worth learning.',NULL,0,0,0,0,0,0,0,0,0),
(61632,'I have come here to teach young trolls about a new type of voodoo. You be looking eager to learn.',NULL,0,0,0,0,0,0,0,0,0),
(61633,'Ya be needing training mon. You have a lot to learn.',NULL,0,0,0,0,0,0,0,0,0),
(61634,'What a weird place, mon. I much prefer wall of Zul\'Aman to... this.$B$BIf ya be needing training, I be here.',NULL,0,0,0,0,0,0,0,0,0),
(61635,'We, Farraki, have been saved by Vol\'jin. Now it be our time to return the favor.$B$BCome closer, I will show you our magic.',NULL,0,0,0,0,0,0,0,0,0),
(61636,'Da dark voodoo that we wield be often overlooked by others. They be gravely mistaken.',NULL,0,0,0,0,0,0,0,0,0),
(61637,'I be offering a collection of grimoires for demons. Be wary, the knowledge there be deadly.',NULL,0,0,0,0,0,0,0,0,0),
(61638,'What is it that you need?',NULL,0,0,0,0,0,0,0,0,0),
(61639,'Looking to prove yourself in the arena?',NULL,0,0,0,0,0,0,0,0,0),
(61641,'Yo pal! Welcome to my studio! It\'s a little crowded, but I make due.$B$BYou\'re talkin\' to Zappo Zapblast, your favorite broadcasting DJ, live from Everlook! Tune in to my show sometime, a\'ight?',NULL,0,0,0,0,0,0,0,0,0),
(61644,'Welcome to the Gnomeregan Reclamation Facility! If you are looking for refuge from the cold snow, there is no better place.',NULL,0,0,0,0,0,0,0,0,0),
(61653,'The Wolfskull Clan was grown from a great vision of one pack struggling against the growing dark. A pack of Wolves within the Horde, one built upon honor, tradition and forgiveness. The corruption that I and so many others cruelly brought upon us. Now rejected as shown in Grom\'s death and in our future. It reminds me of days I can only struggle to remember when the old home of the Orcs was a brighter place. $B$BPerhaps you will join us on our hunt before the eyes of the Earth Mother close and the final darkening of the world comes.',NULL,0,0,0,0,0,0,0,0,0),
(61720,'The only way to make it big as a goblin is by mining. You can very well make it, and become rich!',NULL,0,0,0,0,0,0,0,0,0),
(61721,'You looking for a good deal? If so, you\'ve come to the right place, all of my wares are priced to perfection.',NULL,0,0,0,0,0,0,0,0,0),
(61724,'Welcome to Rustgate Ridge. I am going to assume you are friends of our supreme overseer himself, as he does not allow just anyone to reside within his tower.$B$BIf you are waiting to meet with him, I would suggest taking a seat and finding something warm to eat. His schedule has made him quite busy as of late. That and he has a very large temper.',NULL,0,0,0,0,0,0,0,0,0),
(61725,'What do you want? Do you know how much work needs to be done around here?! Unless you have got something important to tell me or some good news, get out of here.',NULL,0,0,0,0,0,0,0,0,0),
(61726,'You really have to be careful out here! It\'s like all of nature itself is trying to kill an upstanding and working goblin from making a few copper. If you like I can show you how to make some bandages. They can really help out in the wild when some nasty critter gives you some vile wound.$B$BTrust me it\'s really worth the money.',NULL,0,0,0,0,0,0,0,0,0),
(61728,'You looking to spice your life up? Those coal miners down there eat nothing but dirt. We here in the tower eat like kings. You learn a thing or two from me, and who knows, maybe you can eat like a king too.',NULL,0,0,0,0,0,0,0,0,0),
(61729,'Pah, just look at them. Standing around, twiddling their thumbs. How is a good and honest goblin like myself gonna make some marginable profit with conditions like these? A group of armless gnomes is more productive than this bunch. Heck, even a group of gnomes WITH arms would do better.$B$BBlastentom is a cretin and amateur if he believes me to return with a positive business report. Now scram or I\'m giving you a headstart straight down myself for wasting my time AND money.',NULL,0,0,0,0,0,0,0,0,0),
(61730,'What now, Did Taxxlo send you?$B$B<Maxlo lets out a sigh of breath.>$B$BFor a brother, he sure is a bit overbearing. I\'m in charge of the supply around here, and whilst we have excess, it can all evaporate rather quickly if we get reckless.',NULL,0,0,0,0,0,0,0,0,0),
(61732,'If you wanna start catching those big, profitable fish you\'re going to need all the help you can get. Check out my wares and you can find what you\'re looking for.',NULL,0,0,0,0,0,0,0,0,0),
(61733,'Our work quotas and schedules are being pushed up due to a manpower shortage. All of our workers are now grinding even longer shifts to pick up the slack from all those that keep quitting!',NULL,0,0,0,0,0,0,0,0,0),
(61737,'So many lazy workers around here. Such standards and practices would never stand in the Venture Co. I can\'t believe the Durotar Labor Union would even allow such good conditions.',NULL,0,0,0,0,0,0,0,0,0),
(61738,'The good thing about us goblins having only four fingers is that most people won\'t notice if one or two are missing. Neat, isn\'t it?',NULL,0,0,0,0,0,0,0,0,0),
(61739,'If you want to know how to gather some of the more sturdy herbs out there, ya gotta pay me. I ain\'t doing anything for free under these conditions!',NULL,0,0,0,0,0,0,0,0,0),
(61740,'If supplies are low, you gotta improvise! Some herbs here, some body parts there - as long as you can advertise it, someone WILL buy it.',NULL,0,0,0,0,0,0,0,0,0),
(61741,'I really do have my work cut out for me!$B$BA batch of miscalculated fuses and faulty wires has sent all of the robots into chaos here!',NULL,0,0,0,0,0,0,0,0,0),
(61742,'If you\'re looking for a good weapon, or some decent protection, you have come to the right place.',NULL,0,0,0,0,0,0,0,0,0),
(61744,'I have an important job here. Supplying water on Blackstone is about as important as it gets. If this pump was to ever stop working, or if I left my post, it\'d be utter chaos. No active pumps means no drinking water for Rustgate and his goons.$B$BYou\'d think I\'d be paid a little more.',NULL,0,0,0,0,0,0,0,0,0),
(61746,'Let me guess, you\'re here from Rustgate Ridge asking about the water shortages?',NULL,0,0,0,0,0,0,0,0,0),
(61747,'Not much foot traffic gets up around here.$B$BYou wouldn\'t happen to be one of those Venture Co. lurking around are you?',NULL,0,0,0,0,0,0,0,0,0),
(61748,'Well, hello there.$B$BWelcome to my Workshop. I do all sorts of tinkering projects around here, when I get the spare time, that is. Most of my work these days is dedicated to fixing up some things from Rustgate Ridge.$B$BThey can\'t even seem to keep a shredder operational around there. Rusted bolts, torn wiring, cracked frames, it\'s a real mess.',NULL,0,0,0,0,0,0,0,0,0),
(61749,'You wouldn\'t happen to have some spare screws would you?',NULL,0,0,0,0,0,0,0,0,0),
(61754,'What a catastrophe, how are we ever going to earn some coin now?',NULL,0,0,0,0,0,0,0,0,0),
(61755,'You might think I\'m lucky to be standing here, but the truth is I had quite a lot of gold on that ship, all dragged to the bottom of the ocean... I might rather be dead at this point.',NULL,0,0,0,0,0,0,0,0,0),
(61756,'We Thunderforges are te best what Wildhammer smithin\' can offer ye! Blood, sweat an\' tears is what makes our craft one o\' a kind!',NULL,0,0,0,0,0,0,0,0,0),
(61757,'The Bronzebeard dwarves down in Ironforge might pride themselves on their skills, but they pale in comparison to the Wildhammer\'s years of refined craftsmanship.',NULL,0,0,0,0,0,0,0,0,0),
(61758,'Me boys are bundles of talent, but ye got to keep \'em in check. If they would stop bickerin\' for just one day, passin\' down te family traditions te them wouldn\'t be so hard fer me!',NULL,0,0,0,0,0,0,0,0,0),
(61760,'Everything around here is practically in a state of disrepair. Gazzik does a good job helping when he has free time.',NULL,0,0,0,0,0,0,0,0,0),
(61761,'Those blasted Mudpaw drove us out of the mine. Our schedules are all kinds of messed up!',NULL,0,0,0,0,0,0,0,0,0),
(61772,'Cursed by our gluttony, we now stand close to our soon-to-be demise. See us as we stand, shattered, broken, and wretched amidst the rubble and the unwanted muck of our brethren. They have cast us aside, claiming they shall seek the salvation we cannot desire.',NULL,0,0,0,0,0,0,0,0,0),
(61773,'Our suffering knows no end. Can you help us?','Our suffering knows no end. Can you help us?',0,0,0,0,0,0,0,0,0),
(61799,'In the ashes of our once-proud kingdom, we find ourselves, hollow and scarred by the betrayals that have stripped us of everything.$B$BYet, in this desolation, a bitter resolve takes root, for we stand not as defeated remnants but as a united force, forged anew with a singular purpose. The future, once dictated by the whims of the traitorous prince, now lies open before us, a blank canvas upon which we can inscribe our own destiny.',NULL,0,0,0,0,0,0,0,0,0),
(61800,'In the midst of our ceaseless debates on the fate of our people, the answer lies crystal clear before us. Time, a precious resource we squander in endless deliberations, is better spent on the singular, unyielding purpose that binds our hearts—we must reclaim Quel\'Thalas from the clutches of the Scourge, employing any means necessary to usher our homeland back into our embrace.',NULL,0,0,0,0,0,0,0,0,0),
(61801,'Once, in the echoes of a time that now feels like a distant fantasy, I dreamed of donning the mantle of Ranger-General. A vision painted with the vibrant hues of ambition danced before my eyes. Yet, the years have woven a different tapestry, one marked by the harsh brushstrokes of reality.$B$BThe coveted title, once a beacon of achievement, has transformed into a weighty burden resting heavily upon these weathered shoulders of mine.',NULL,0,0,0,0,0,0,0,0,0),
(61802,'Loathe though I am to do this to her, it seems that despite her best efforts Vereesa has not been able to handle her responsibilities on her own. For the good of our people we must look to someone else for leadership.$B$BSadly, some here cling to the past, hindering our progress. Perhaps the responsibility of the crown is too much for one head in these circumstances, yet reluctance is ever the companion of fear of change.$B$BWe must put our people first and cast aside antiquated loyalties to usher in a new, better era.',NULL,0,0,0,0,0,0,0,0,0),
(61803,'Vereesa\'s ineptitude in rallying Alliance forces to reclaim Quel\'Thalas marks the last straw. I refuse to witness our proud race reduced to a puppet state of Stormwind. With our reliance on the Alliance military, we stand exposed to the threats of both the Scourge and the resurgent Amani tribe.$B$BIt is only a matter of time until others recognize my rightful claim to leadership. The Sunsworn dynasty shall ascend, and under my rule, we will endure for countless millennia. The era of vulnerability and subservience is over; the dominion of the Quel\'dorei shall be reestablished, unyielding against external threats.',NULL,0,0,0,0,0,0,0,0,0),
(61804,'In a bygone era, I stood as the closest confidant and advisor to Prince Kael\'thas, watching with sorrow as he forsook us, seduced by the malevolent powers of the Legion.$B$BThough I yearn for his return, the wisps of foresight that caress my ancient senses reveal a path fraught with uncertainty.$B$BHope lingers, but I am no fool. In the absence of our prince, we must face the harsh reality and select a temporary leader to guide our people through these tumultuous times.',NULL,0,0,0,0,0,0,0,0,0),
(61805,'Hm? Oh, bal’a dash, friend. Is there something I can help you with? As you can see, we are in the midst of quite the dilemma.$B$BWith the throne in play, I imagine it will be a rather dramatic debate. If nothing else, let none say that the Quel’dorei are not a passionate people.$B$BI wonder, who would you support in this clash?',NULL,0,0,0,0,0,0,0,0,0),
(61807,'Welcome to Brinthilien. I hope the journey wasn\'t too hard on you.',NULL,0,0,0,0,0,0,0,0,0),
(61822,'Enchanting is a noble art. Can you handle it?',NULL,0,0,0,0,0,0,0,0,0),
(61831,'Rest, weary traveler, for your burdens weigh heavy. In this newfound sanctuary, our collective haven, endure we shall, resilient against the trials that have befallen us.',NULL,0,0,0,0,0,0,0,0,0),
(61832,'Welcome to Brinthilien. I trust the journey hasn\'t been too arduous for you.',NULL,0,0,0,0,0,0,0,0,0),
(61836,'The once-exquisite silks of our craftsmanship now lie ravaged and torn amidst the ruins of Silvermoon. It falls upon us, the artisans of the high elves, to weave anew and restore the resplendent glory that is rightfully ours.',NULL,0,0,0,0,0,0,0,0,0),
(61837,'Before the fall of Quel\'Thalas, I served as the apprentice to the esteemed Ley-Technician Fenros. With his unfortunate demise, the responsibility now falls upon my shoulders as the sole bearer of this invaluable knowledge, entrusted with the task of passing it down to the generations that follow.',NULL,0,0,0,0,0,0,0,0,0),
(61840,'I am the finest leatherworker in Alah\'Thalas. And I\'m willing to share my knowledge.',NULL,0,0,0,0,0,0,0,0,0),
(61841,'I am of the firm belief that our pursuits should not be constrained by the moral dictates of the Regency Council. The arcane is a vast tapestry, woven with threads beyond our current understanding, and I am resolved to unveil its hidden secrets.',NULL,0,0,0,0,0,0,0,0,0),
(61842,'Ah, another young apprentice comes to me to learn about the secrets of nature.',NULL,0,0,0,0,0,0,0,0,0),
(61846,'I love fishing. I came here to see if there\'s any new species of fish to catch here, and these waters do not disappoint.',NULL,0,0,0,0,0,0,0,0,0),
(61849,'Lady Windrunner speaks true, and under her command, our people thrived. The Regency Council\'s treachery will never hold sway over warriors like us; our loyalty lies solely with Lady Windrunner.$B$BWe\'ll follow her lead, undeterred by the machinations of those who betray our kin. In the heat of battle, it\'s Lady Windrunner\'s banner we rally behind, forging our path with the unyielding strength of warriors who recognize true leadership.',NULL,0,0,0,0,0,0,0,0,0),
(61851,'Welcome to Brinthilien, young $c. May the Eternal Sun shine upon you.',NULL,0,0,0,0,0,0,0,0,0),
(61861,'What brings you around Powder Town? Are you seeking fortune, or do you like just a spark of danger in your life?',NULL,0,0,0,0,0,0,0,0,0),
(61887,'Stonetalon has always held such natural beauty.',NULL,0,0,0,0,0,0,0,0,0),
(61894,'Our research here is proving to be quite extensive. To find the cure for the intense desire of arcane that molds our very essence is a monumental task. One only us elves may be worthy of discovering.',NULL,0,0,0,0,0,0,0,0,0),
(61902,'There\'s a thing or two to know about fashion darling. If you aren\'t sporting some designer brands or the newest most up to date threads you\'re not fashionable, it\'s that easy.$B$BI promise if you take one look at what we have, you\'ll be blown away by our quality!',NULL,0,0,0,0,0,0,0,0,0),
(61903,'There is no better way to get into the festive spirit than to dress appropriately!',NULL,0,0,0,0,0,0,0,0,0),
(61904,'The snow always makes me feel festive. Even with my cold, dark soul.',NULL,0,0,0,0,0,0,0,0,0),
(61906,'I know a thing or two about the jewelcrafting trade, but if you want to learn some of the most advanced patterns, you will need to speak with my father. He knows all the tricks of the trade.',NULL,0,0,0,0,0,0,0,0,0),
(61907,'Our family is well reputed within Stormwind for our trade. We have taken commissions from the nobility for some of the finest pieces of jewelry in all of the kingdom.',NULL,0,0,0,0,0,0,0,0,0),
(61908,'Is there anything that I can help you with?',NULL,0,0,0,0,0,0,0,0,0),
(61910,'My great-grandfather was a jeweler within the great city of Gim Batol. It is my aspiration to match his expertise in the craft.',NULL,0,0,0,0,0,0,0,0,0),
(61911,'You know what they say about good jewelcrafting! Keep a steady hand and a steady mind, and you will create true art.$B$B<Torvag begins to laugh unctonrollably.>$B$BMy name is Torvag! If you see me around, feel free to say hello. Perhaps we can work together and create something truly beautiful.',NULL,0,0,0,0,0,0,0,0,0),
(61912,'Don\'t pay much mind to Torvag. He\'s overly enthusiastic and a bit quirky, but he is truly dedicated to his work.$B$BIf you\'re looking for any advanced methods in jewelcrafting, I\'m your gnome!',NULL,0,0,0,0,0,0,0,0,0),
(61913,'The properties of gold seem to blend well with Star Ruby to create ornate jewelry with stunning appeal. A little tinkering with the shape and proportions could...$B$B<Fanzy is snapped back to reality.>$B$BHey, what are you doing here? Can\'t you see I\'m deep in study?$B$BOh, you\'re looking to learn advanced jewelcrafting? Well, you had better have a deep understanding of the vast and complex science of jewelcrafting before I even humor the thought of teaching you.',NULL,0,0,0,0,0,0,0,0,0),
(61916,'The intricate nature of jewelcrafting is quite well suited to elvish tastes.',NULL,0,0,0,0,0,0,0,0,0),
(61917,'There are many places to focus our arcane transfixation. I have found solace within my art, the creation of delicate displays of beauty. Most often seen in the form of gold and silver worn upon ones body.$B$BThere is a grace in it, is there not?',NULL,0,0,0,0,0,0,0,0,0),
(61918,'Welcome to Asoran\'s Jewelry... Yeah I know, I used to have a shop here that did other things, but this is a new business venture.$B$BYou looking to learn something?',NULL,0,0,0,0,0,0,0,0,0),
(61919,'Once our war with the humans came to an end, it was time to focus my attention on other things. I have always had a keen eye for shiny objects and gleaming crystals.',NULL,0,0,0,0,0,0,0,0,0),
(61921,'My cold, numb fingers are having trouble with such delicate work!',NULL,0,0,0,0,0,0,0,0,0),
(61923,'Jewelry has always been a striking accessory. Now that we are decaying, there may be even more of a reliance on it. Even in death, we must still look our best.',NULL,0,0,0,0,0,0,0,0,0),
(61924,'My family have been jewelcrafters for our entire lineage. They once owned a shop in Stratholme and created some of the finest necklaces in all of Azeroth.$B$BI still remember gazing upon some of my father\'s work in awe.',NULL,0,0,0,0,0,0,0,0,0),
(61925,'Everyone needs jewelry, especially in the goblin world. How else are you going to flex your wealth on your peers?$B$BIt can also make your social status climb. A couple silver rings will have you getting all the ladies.',NULL,0,0,0,0,0,0,0,0,0),
(61927,'Listen here pal, if you want to make the real money I have the secrets for you. You think gold is valueable? Try turning it into luxury pieces of jewelry!$B$BI\'ve had some of my creations go for insane profits at auction, and you can do the same. All you gotta do is follow my easy steps and you too can hit big in the world of jewelcrafting!',NULL,0,0,0,0,0,0,0,0,0),
(61930,'Greetings, weary traveler. Are you here for some... good and honest trade?',NULL,0,0,0,0,0,0,0,0,0),
(61931,'<His gaze is intimidating.>',NULL,0,0,0,0,0,0,0,0,0),
(61973,'Eh, if you value your life, you\'d better not stick your nose into the business of others...',NULL,0,0,0,0,0,0,0,0,0),
(61977,'I just can\'t catch a break.',NULL,0,0,0,0,0,0,0,0,0),
(61979,'Who do you think you are? Can you not meddle in other people\'s affairs?',NULL,0,0,0,0,0,0,0,0,0),
(61988,'The ghostly apparition seems to be fading in and out of two different planes of existence.',NULL,0,0,0,0,0,0,0,0,0),
(61990,'Have you seen big candle? Me look for big candle!',NULL,0,0,0,0,0,0,0,0,0),
(61991,'Get lost, idiot. Leave me to my booze.',NULL,0,0,0,0,0,0,0,0,0),
(61992,'So much dust and the company is horrible, too. This place has seen better days.',NULL,0,0,0,0,0,0,0,0,0),
(61997,'This place is a total mess. Everything is in total disarray. The food offerings are sparse at best, the company more than questionable and things randomly start disappearing! I\'ve been looking for my ring for hours! I cannot fathom what has gotten into Medivh, but this is absolutely not the way to treat your guests.',NULL,0,0,0,0,0,0,0,0,0),
(61998,'<The young woman is sulking and looks depressed.>',NULL,0,0,0,0,0,0,0,0,0),
(61999,'The master wishes these energy crystals to be active at all times, but ever since someone stole the ignition key, I cannot get them to start up. I have to fix this before he returns!',NULL,0,0,0,0,0,0,0,0,0),
(62000,'Oh, I haven\'t seen you with all this chaos going on here. The Master will soon return and his beloved bananas aren\'t in any of the fruit bowls! This is a disaster!',NULL,0,0,0,0,0,0,0,0,0),
(62001,'Who could\'ve known the Guardian\'s literature is written in such miniscule letters? It\'s giving me the biggest of headaches!',NULL,0,0,0,0,0,0,0,0,0),
(62002,'No matter how long I\'m standing at this fire, it just doesn\'t warm me up! Being a ghost is just a hassle sometimes.',NULL,0,0,0,0,0,0,0,0,0),
(62003,'Good day to you! Isn\'t the view something else? I don\'t think there is anything that can compare to the magnificent tower of Medivh. Did you know it was built on a focal point of ley lines? Incredible, right? Let\'s drink on that, my friend!',NULL,0,0,0,0,0,0,0,0,0),
(62007,'Let the Moon guide through the night, and let the sun warm your bones during the day.',NULL,0,0,0,0,0,0,0,0,0),
(62030,'The intricate magic of this place is waiting to be exploited... If you explore enough of this tower, and clear it from the evil that lurks here, I could transport you with my rift walking.',NULL,0,0,0,0,0,0,0,0,0),
(62031,'In my years upon Azeroth I have dedicated myself to becoming a master of arms. Now that I have learned all that I can from the various races I look to the past to find techniques that may be lost to time itself. If you can assist me in finding these rare artifacts I can dispense with the knowledge that I have acquired.$B$BYou can find Ancient Warfare Text from some of the more dangerous parts of Azeroth. These documents contain information on how battle, warfare, and single combat were fought in days past, and can potentially unlock unknown combat techniques.',NULL,0,0,0,0,0,0,0,0,0),
(62032,'Mathias has put his heart and soul into his work. It has inspired me to follow in his footsteps. There may be a day when I take his stead and continue his work long from now.',NULL,0,0,0,0,0,0,0,0,0),
(62033,'All of the fighting that takes place on this island can sure build hunger. If you need something to eat, let me know.',NULL,0,0,0,0,0,0,0,0,0),
(62034,'Why hello there, my name is Nora, I came as a good friend to Mathias. My job here is to decipher some of these old texts! Some are written in old runes or glyphs that would be impossible to translate without the proper knowledge.',NULL,0,0,0,0,0,0,0,0,0),
(62063,'De sands be cruel and without compromise. Perfect ground for training.',NULL,0,0,0,0,0,0,0,0,0),
(62994,'These brutes are everywhere. I really wish the chieftain would finally do something about it.','These brutes are everywhere. I really wish the chieftain would finally do something about it.',0,0,0,0,0,0,0,0,0),
(65003,'I don\'t suppose you\'re here for a mere chit-chat. Take a rest, spend your coins and leave me be, mortal.',NULL,0,0,0,0,0,0,0,0,0),
(65013,'This place is quite puzzling, but it has great business!',NULL,0,0,0,0,0,0,0,0,0),
(66004,'<An eerie gaze pierces your soul.>',NULL,0,0,0,0,0,0,0,0,0),
(80100,'First day on the job, eh kid?\n\nYeah, I used to be young and green like you once. Now I\'m just green! What can you do, eh?\n\nAnyway, enough slacking. Back to work or I\'m taking it out of your pay!',NULL,0,0,0,0,0,0,0,0,0),
(80104,'Hey pal, looking for some training in how to rough somebody up?\n\nHere\'s some advice: First, you go for the knees. Once they\'re at your level, they won\'t be lookin\' down on you no more. Catch my drift?\n\nThat\'s solid advice. You owe me a few copper for it.',NULL,0,0,0,0,0,0,0,0,0),
(80105,'Guns. Man, I love guns. Don\'t you, $N?\n\nEverytime I hear that thundering BOOM, it gets my blood pumping. Need some firearm training? If you got the coin, I got the skills.',NULL,0,0,0,0,0,0,0,0,0),
(80106,'What\'s better than a bag of coins, $N? A bag of coins you pilfered from some sucker\'s pocket. Better than that? One you pried from their cold, dead hands.\n\nI hear you can sell a whole body for some nice coin, too... So don\'t test me.',NULL,0,0,0,0,0,0,0,0,0),
(80107,'Nobody ever suspects the goblins, $N. Nobody! So who\'s going to think twice about a little dabbling in the dark arts?\n\nI bet you\'re just itching to learn how to summon a succubus... or maybe your tastes are inclined towards an incubus? Business before pleasure, pal. Coin first, summoning spells after!',NULL,0,0,0,0,0,0,0,0,0),
(80108,'Hey there, best pal! You looking to try your hand at some magic? Wizardry? You look like you got big brains like me. You could make a lot of coin with spells like these.\n\nConjure up some water, some food, open portals. All these conveniences mean one thing: Cha-ching! Of course, you\'ll have to slide me some coin if you want to make some coin, feel me?',NULL,0,0,0,0,0,0,0,0,0),
(80121,'Durotar ain\'t exactly a vacation destination. Sand and scorpids and harpies, and apparently they\'ve added some sort of demonic cult since my last visit. Still, it\'s better than finding yourself on the wrong end of a Venture Co. brute squad.\n\n<Nert sighs.>\n\nI used to be the brute squad.\n\nAnyways, a good businessman is always looking forward. Where there\'s scarcity, there\'s opportunity. The Horde seems to specialize in colonizing the most hostile wastelands on the face of Azeroth, so with enough know-how, I bet I can make enough to vacation on the South Sea island of my choice.',NULL,0,0,0,0,0,0,0,0,0),
(80131,'Can\'t you see I am busy sweeping around here?',NULL,0,0,0,0,0,0,0,0,0),
(80136,'I don’t just teach anyone, pal. Come back to me when we’re on better terms.',NULL,0,0,0,0,0,0,0,0,0),
(80200,'Thank the Sunwell you made it here in one piece, $N. We have much to do.',NULL,0,0,0,0,0,0,0,0,0),
(80217,'Our people pride themselves on their intellect and their mastery of magic, but you and I both know that occasionally, a more forceful approach is necessary.',NULL,0,0,0,0,0,0,0,0,0),
(80218,'Ever since the Sunwell fell, we\'ve strained to minimize the amount of mana we expend. We used to be paragons of arcane power; now, we are a mere shadow of our former selves.',NULL,0,0,0,0,0,0,0,0,0),
(80219,'The Farstriders were a proud group of rangers. With the downfall of our homeland, most of them, too, have passed away. Still, their legacy will live on through us.',NULL,0,0,0,0,0,0,0,0,0),
(80220,'It is only by the grace of the Light that we stand here today, and we will be the ones to defend our people against the Scourge and other threats. However, remember that justice is to be dealt fairly, not blindly guided by vengeance.',NULL,0,0,0,0,0,0,0,0,0),
(80221,'These are bleak times, but our kin must be guided towards the Light. Their wounds, while they cannot be healed entirely, must be attended to with all our might.',NULL,0,0,0,0,0,0,0,0,0);
INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`,`chat_type`,`sound_id`,`language_id`,`emote_id1`,`emote_id2`,`emote_id3`,`emote_delay1`,`emote_delay2`,`emote_delay3`) VALUES
(80223,'Whether you want to steal from a noble\'s pocket, explore the dark corners, or break into a chest, always remember the Sunwell.',NULL,0,0,0,0,0,0,0,0,0),
(80227,'You have journeyed a great distance. Rest your weary body under our roof, and may the Sun guide you.',NULL,0,0,0,0,0,0,0,0,0),
(80243,'These are dark times, $N, but we must guide our kin to the Light, and we must tend to their wounds as best as we can.',NULL,0,0,0,0,0,0,0,0,0),
(80244,'It is by the blessings of the Light we both stand here today, $N, we will be the ones to avenge our people, against the Scourge and other threads, but remember the teachings, vengeance by justice.',NULL,0,0,0,0,0,0,0,0,0),
(80245,'The Farstriders were a proud group of rangers, with the fall of our land they too have been left behind, yet it is in us that their legacy will live on.',NULL,0,0,0,0,0,0,0,0,0),
(80246,'With the Sunwell gone, we strife to use as little mana as possible, we used to be a pillar of the Arcane, $N, now look at us.',NULL,0,0,0,0,0,0,0,0,0),
(80247,'Our kin prides itself with intellect and magic, but you and I know that sometimes a more brutish approach is needed.',NULL,0,0,0,0,0,0,0,0,0),
(80248,'Whether you want to steal from a noble\'s pocket, crawl into the shadows or lockpick someone\'s chest, remember the Sunwell.',NULL,0,0,0,0,0,0,0,0,0),
(80450,'Greetings, $C, are you here to aid us? If so I will be more than rejoiced, as soon as we stabilize the barrier or neutralize the targets, the better, you have no idea what crawls in there.',NULL,0,0,0,0,0,0,0,0,0),
(80451,'Hi, how are you?\n\nI’m Koli, here to make sure we deal with this, please be friendly to one another, no time to squabble!\n\nThere will be enough violence when you reach inside.',NULL,0,0,0,0,0,0,0,0,0),
(80452,'I teach only elves of Silvermoon Remnants and their allies.',NULL,0,0,0,0,0,0,0,0,0),
(80460,'I wish I knew an older, wiser tree. Trees are supposed to have beautiful foliage, but mine is wilted and dying.\n\nAm I going to survive?	',NULL,0,0,0,0,0,0,0,0,0),
(80601,'Hey, if you aren\'t spending coins, you might as well get out. You\'re bothering my real customers.',NULL,0,0,0,0,0,0,0,0,0),
(80602,'Heya, sweetie. Here to make a long time investement?\n\nMaybe you wanna gamble, little $c? Tell me how much and I\'ll throw the dice. If the roll is above 50, I will double the bet. If it’s lower than 50, it\'s gone forever.\n\nIf you win three times in a row using the same amount, the reward is tripled, but only if the 3rd roll is above 75. If it’s below 75 on the 3rd roll, your gold will be gone too.',NULL,0,0,0,0,0,0,0,0,0),
(80603,'<The Goblin Bruiser stands with his chest puffed up and continues to mumble under his breath.>',NULL,0,0,0,0,0,0,0,0,0),
(80605,'My gut feelin\' be tellin\' me there\'s something more going on \'round this bar.',NULL,0,0,0,0,0,0,0,0,0),
(80855,'Don\'t underestimate what a gnome with a gun can do, $c!',NULL,0,0,0,0,0,0,0,0,0),
(80877,'In our people\'s most trying times, it was my unwavering commitment that brought us together to forge this sanctuary of hope. Through earnest efforts, I mended the bonds between our kin and the Alliance, restoring the trust that had faltered. I never sought regal titles or aspirations of grandeur, merely recognizing the pressing need for steadfast leadership.$B$BYet, in the halls of our own kin, where nobility should be defined by honor and foresight, a blindness persists. The noble families, entangled in webs of influence and wealth, fail to perceive the true nature of our collective journey. Unjustly stripped of the title of Speaker, a position embraced not for personal gain but for the welfare of our people, I stand witness to a disheartening diversion of focus.$B$BInstead of marshaling our resources and collective wisdom to face the pressing challenges that loom before us, we find ourselves mired in needless debates that obscure the clarity of our path forward.',NULL,0,0,0,0,0,0,0,0,0),
(80925,'Why hello there, $c, is there anything I could do for you?',NULL,0,0,0,0,0,0,0,0,0),
(80943,'Are you looking to gain standing with the Wardens, mortal? Are you looking to keep harmony within the strands of time?\n\nLook no further then here, each day we remain idle is another day that chaos begins to tear apart order.\n\nThe forces that seek to undermine our work will not stop. There is always more that can be done, and you are here for that very reason, are you not?',NULL,0,0,0,0,0,0,0,0,0),
(81050,'I am truly privileged that the Dark Lady has entrusted me with sharing her knowledge.',NULL,0,0,0,0,0,0,0,0,0),
(90252,'Latest news from the best race event ever! Come and get your own magazine!',NULL,0,0,0,0,0,0,0,0,0),
(90260,'The Gadgetzan Times, Volume Two, available now! Worth its weight in gold... metaphorically speaking!',NULL,0,0,0,0,0,0,0,0,0),
(90317,'Another fool walks into his death. Come then, let me show you what happens to those who oppose the Bloodsail!',NULL,0,0,0,0,0,0,0,0,0),
(90320,'You were a fool to come here, this is Defias land now.','',0,0,0,0,0,0,0,0,0),
(90352,'If you have a garden and a library, you have everything you need.',NULL,0,0,0,0,0,0,0,0,0),
(90353,'My grand dream is to grow the World\'s Biggest Pumpkin!\n\nWhat\'s yours?',NULL,0,0,0,0,0,0,0,0,0),
(90354,'Ahh, Ive been expecting you, $N.\n\nHere to learn how to foster the seeds and care for the soil?\n\nYou\'re just in time.',NULL,0,0,0,0,0,0,0,0,0),
(90355,'I\'m here to study the art of Survival under one of the wisest elders of the Mosshoof tribe, shando Kern.\n\nMy sister tend to the wounds, teaching First Aid and I\'m certain that healing comes from the Earth-Mother much more than any bandage could ever heal, gifts of the Earth itself.\n\nGrowing food is an art I\'m eager to know as good as my own hooves.',NULL,0,0,0,0,0,0,0,0,0),
(90361,'Those spiders aren\'t anything I ever killed.\n\nFull group, no … three would be needed to even scratch that beast there.\n\nNever go alone in these lands! Never!',NULL,0,0,0,0,0,0,0,0,0),
(90362,'Hey, you! We could use your help here!',NULL,0,0,0,0,0,0,0,0,0),
(90987,'Our ship got wrecked a few weeks ago, I\'ve been managing to survive. The murlocs can certainly cause issues, are you willing to help?',NULL,0,0,0,0,0,0,0,0,0),
(91190,'What brings you to the stead?',NULL,0,0,0,0,0,0,0,0,0),
(91191,'The Argent Dawn fights in far away lands to maintain order within Azeroth, even as chaos lurks.',NULL,0,0,0,0,0,0,0,0,0),
(91200,'It\'s all about goblin precision, you think an orc could work such delicate parts?\n\nWhatcha need, bub?',NULL,0,0,0,0,0,0,0,0,0),
(91201,'Cutting wood isn\'t easy work, especially with all these lazy louts!\n\nIt\'s what good foremen like me are here for, up productivity!',NULL,0,0,0,0,0,0,0,0,0),
(91202,'Hey there, if you\'re looking to produce your own potions to save a few coins, you\'ve come just to the right place!',NULL,0,0,0,0,0,0,0,0,0),
(91204,'Unless you have a drink for me, you\'d best shove up, whelp!',NULL,0,0,0,0,0,0,0,0,0),
(91205,'If you\'re lookin\' for odds and ends from across the south seas, then you\'re in luck!\n\nThere\'s no other place you can get this stuff than right here at Zeet\'s!\n\nOh, and NO REFUNDS!',NULL,0,0,0,0,0,0,0,0,0),
(91216,'Wuzgut make sure no one steal lumber, you buy?',NULL,0,0,0,0,0,0,0,0,0),
(91220,'Lozzle the Nozzle here! You\'re looking awfully thirsty, the sweat rolling off your face, the hot sun beating down on someone would do JUST that!\n\nWhy don\'t you grab some of my water, it\'s ice cold, and quenches the thirst, priced JUST right!\n\nNot like you\'ll find any other in town.',NULL,0,0,0,0,0,0,0,0,0),
(91221,'You lookin\' for your fix, bub? I got the good stuff, cheap, and home made!\n\nIt will get you drunk faster than any of that silly Dalaran wine, that\'s for sure. Shows you what a goblin with his mind set to a task can do.',NULL,0,0,0,0,0,0,0,0,0),
(91225,'Welcome to Sparkwater!\n\nI designed and built this place from the ground up, from the very first stone and rock into what it is now.\n\nSo, if you got any building projects, let me know. It may cost a pretty penny, but it\'s worth the gold, I\'ll tell you THAT much!',NULL,0,0,0,0,0,0,0,0,0),
(91227,'Throm-Ka, friend. The goblins surely have a taste for fine meat, and it would seem they eat quite the filling of it.',NULL,0,0,0,0,0,0,0,0,0),
(91229,'I been hearin\' the platform got overrun by the sea crawlers they better not come bother me any!',NULL,0,0,0,0,0,0,0,0,0),
(91230,'My job here is to make sure the port is safe. Any unknown ships come into range, I fire this bad girl at them. Iron ball packed tight to the brim with gun powder will sink any vessel that is stupid enough to mess with us.',NULL,0,0,0,0,0,0,0,0,0),
(91231,'Missfire Shmissfire! We\'re ordered to pack this baby full of powder when we see something!\n\nWe\'ll probably hit the eastern kingdoms!',NULL,0,0,0,0,0,0,0,0,0),
(91232,'Heh, you lookin\' to get smarter, huh? Well, reading some of these scrolls or books certainly could expand your knowledge, a few of them for a little while for sure!',NULL,0,0,0,0,0,0,0,0,0),
(91238,'Hey! Welcome to the Sparkwater Tavern!\n\nMake yourself at home and find a table! If you need any drinks, come talk to me.',NULL,0,0,0,0,0,0,0,0,0),
