INSERT INTO `broadcast_text` (`entry`,`male_text`,`female_text`,`chat_type`,`sound_id`,`language_id`,`emote_id1`,`emote_id2`,`emote_id3`,`emote_delay1`,`emote_delay2`,`emote_delay3`) VALUES
(30197,'I do not understand, what do you...?',NULL,0,0,0,0,0,0,0,0,0),
(30198,'Sanv K\'la. After years of searching for you and the other lost sheep of mine, you finally reveal yourself.',NULL,0,0,0,0,0,0,0,0,0),
(30199,'Your need for pitiful hiding is over, my brethren. For I have secured us a safe haven in our homeworld, the place you should all return to.',NULL,0,0,0,0,0,0,0,0,0),
(30200,'Join me, as I can give you whatever you desire. Yet, most importantly, I can give you a purpose; a purpose greater than anything you could possibly fathom!',NULL,0,0,0,0,0,0,0,0,0),
(30201,'Anyone eager to follow me back into the fulfilling embrace of our saviors, come forth! And those who wish to defy me...',NULL,0,0,0,0,0,0,0,0,0),
(30202,'Prepare to be cast into the endless oblivion of the Twisting Nether!',NULL,0,0,0,0,0,0,0,0,0),
(30228,'It is done! But... something is amiss...',NULL,0,0,0,0,0,0,0,0,0),
(47046,'SNAKES! RUN! EVERYONE RUN!','SNAKES! RUN! EVERYONE RUN!',1,0,0,5,0,0,0,0,0),
(47047,'I will not forget this, $n!',NULL,0,0,0,1,0,0,0,0,0),
(49300,NULL,'Heroes of the Alliance, thank you for answering our call for help.',0,0,0,1,0,0,0,0,0),
(49301,NULL,'Heroes of the Horde, thank you for answering our call for help.',0,0,0,1,0,0,0,0,0),
(49302,NULL,'I will brief you on the current situation. Listen carefully, as we have only one chance to make this right.',0,0,0,2,0,0,0,0,0),
(49303,NULL,'Agents of the Infinite Dragonflight are seeking to alter history, by changing the outcome of this battle.',0,0,0,5,0,0,0,0,0),
(49304,NULL,'They have disguised themselves as orcish warriors, and are attempting to tip the scales towards a victory for the orcs.',0,0,0,1,0,0,0,0,0),
(49305,NULL,'They have disguised themselves as soldiers of the alliance, and are attempting to tip the scales in their favor.',0,0,0,1,0,0,0,0,0),
(49306,NULL,'If they succeed in their efforts, this will have catastrophic consequences in the present.',0,0,0,274,0,0,0,0,0),
(49307,NULL,'Luckily for us, there is a way to identify their agents, and put an end to their machinations.',0,0,0,1,0,0,0,0,0),
(49308,NULL,'Search the battlefield for flickering time sparks, and turn them in to Alurzion for analysis.',0,0,0,25,0,0,0,0,0),
(49309,NULL,'Once you\'ve collected a total of 100 sparks, the identity of their leader will be revealed.',0,0,0,1,0,0,0,0,0),
(49310,NULL,'But beware, as he will likely turn back into his true form once attacked, and unleash the full strenght of his abilities.',0,0,0,5,0,0,0,0,0),
(49311,NULL,'The more flickering time sparks you turn in, the weaker their leader will become. Holding the central island is the key to victory, as you cannot turn in sparks otherwise.',0,0,0,1,0,0,0,0,0),
(49312,NULL,'Good luck, heroes. The future depends on you.',0,0,0,66,0,0,0,0,0),
(51697,'Check in on me? What does he think he can control me here, and who are you, some worthless constable?',NULL,0,0,0,1,0,0,0,0,0),
(65014,'I invoke the Ancient Pact! Dreamways, open before me.','I invoke the Ancient Pact! Dreamways, open before me.',0,0,0,0,0,0,0,0,0),
(65015,'Something is wrong…','Something is wrong…',0,0,0,0,0,0,0,0,0),
(65016,'I invoke the Ancient Pact! Open the way to the Emerald Dream!','I invoke the Ancient Pact! Open the way to the Emerald Dream!',0,0,0,0,0,0,0,0,0),
(90261,'We Keepers have been active within Azshara to leave the secrets of the region a mystery. We have fallen into shadow, into dissaray unable to even communicate effectively with one another, and spread over large distances. We are surrounded by enemies at all sides and what once was is nothing more then a faded memory of ruins.',NULL,0,0,0,0,0,0,0,0,0),
(90262,'It has been a long time since I have had the chance to wield my magic in such a manner, and now, crafting this Staff of Eldara has granted me some glimmer of hope.',NULL,0,0,0,0,0,0,0,0,0),
(91299,'Okay, okay! Just whatever you say boss!',NULL,0,0,0,0,0,0,0,0,0),
(91300,'Please, no! I have gold, I can p...',NULL,0,0,0,5,0,0,0,0,0),
(4292003,'What does the chieftan\'s son have to do with a Parash\'ka? These are truly dire times. Still, I will not deny my student\'s request, he would not disturb his master for trivialities.','What does the chieftan\'s son have to do with a Parash\'ka? These are truly dire times. Still, I will not deny my student\'s request, he would not disturb his master for trivialities.',0,0,0,0,0,0,0,0,0),
(4292004,'Riftmaster Ral\'pekta inspects the red crystal.','Riftmaster Ral\'pekta inspects the red crystal.',2,0,0,0,0,0,0,0,0),
(4292005,'This crystal is...! No, it couldn\'t... I have to make sure I am wrong!','This crystal is...! No, it couldn\'t... I have to make sure I am wrong!',0,0,0,0,0,0,0,0,0),
(4292006,'Riftmaster Ral\'pekta channels arcane energy into the crystal.','Riftmaster Ral\'pekta channels arcane energy into the crystal.',2,0,0,0,0,0,0,0,0),
(4292007,'Gah!','Gah!',0,0,0,0,0,0,0,0,0),
(4292008,'Impossible, slay this fiend!','Impossible, slay this fiend!',0,0,0,0,0,0,0,0,0),
(6243202,'Far Seer Mothand begins the ritual','Far Seer Mothand begins the ritual',2,0,0,0,0,0,0,0,0),
(6243203,'I can feel the power flowing through my veins!','I can feel the power flowing through my veins!',0,0,0,0,0,0,0,0,0),
(6243204,'It is complete! The power of the Uth\'okk is mine! Behold the energy flowing through my veins!','It is complete! The power of the Uth\'okk is mine! Behold the energy flowing through my veins!',0,0,0,0,0,0,0,0,0),
(6285003,'My son? What is the meaning of this?','My son? What is the meaning of this?',0,0,0,0,0,0,0,0,0),
(6285004,'Ar\'lia, just what are you talking about? What are you accusing me of?','Ar\'lia, just what are you talking about? What are you accusing me of?',0,0,0,0,0,0,0,0,0),
(6285005,'Son, your words are bold and unruly towards me, your father. They cut deep, but can only do so because they are the truth. Yes, I hid things from you, out of shame and in fear of my own weakness.','Son, your words are bold and unruly towards me, your father. They cut deep, but can only do so because they are the truth. Yes, I hid things from you, out of shame and in fear of my own weakness.',0,0,0,0,0,0,0,0,0),
(6285006,'Bhu\'robi had always been critical of out ways, especially after our escape to this world. Our inaction towards the advances of the demonic orcs, while posessing the power of the Draenethyst, is a flaw that he was deeply revolted by.','Bhu\'robi had always been critical of out ways, especially after our escape to this world. Our inaction towards the advances of the demonic orcs, while posessing the power of the Draenethyst, is a flaw that he was deeply revolted by.',0,0,0,0,0,0,0,0,0),
(6285007,'My son, tell me: if you were in mortal danger, would you not do everything you can to survive? In such situations, rationality often subsides in favor of our instincts. Bhu\'robi knew this all too well. I still remember his last words to me as if they were uttered mere moments ago.','My son, tell me: if you were in mortal danger, would you not do everything you can to survive? In such situations, rationality often subsides in favor of our instincts. Bhu\'robi knew this all too well. I still remember his last words to me as if they were uttered mere moments ago.',0,0,0,0,0,0,0,0,0),
(6285008,'You are shackled by your traditions, stuck in the mire of your self-inflicted lethargy. If you wish to rot dwelling on the past, so be it. But I will usher in a new dawn for our people. And then you will see the truth yourself.','You are shackled by your traditions, stuck in the mire of your self-inflicted lethargy. If you wish to rot dwelling on the past, so be it. But I will usher in a new dawn for our people. And then you will see the truth yourself.',0,0,0,0,0,0,0,0,0),
(6285009,'Ar\'lia...','Ar\'lia...',0,0,0,0,0,0,0,0,0),
(6292202,'They\'re coming!','They\'re coming!',0,0,0,0,0,0,0,0,0),
(6292203,'Another group, brace yourself!','Another group, brace yourself!',0,0,0,0,0,0,0,0,0),
(6292204,'Look at that brute! This must be their leader!','Look at that brute! This must be their leader!',0,0,0,0,0,0,0,0,0);
